WITH payload AS (SELECT '[{"id":"c8202611-05c0-4a9b-9f00-000000000001","title":"脑洞急转弯：认真想就输了？","subject":"脑洞谜题","grade_level":"Year 6","language":"zh","description":"20 道古怪又有标准答案的逻辑谜题，挑战直觉与阅读细节。","questions":[{"question":"一年十二个月中，有几个月至少有28天？","options":["12个月","1个月","2个月","只有闰年才有"],"correct_option_index":0,"explanation":"每个月都至少有28天，不只是二月。"},{"question":"桌上有3个苹果，你拿走2个，现在你手中有几个？","options":["1个","3个","0个","2个"],"correct_option_index":3,"explanation":"题目问手中，不是桌上剩下的数量。"},{"question":"1千克棉花与1千克铁块，哪个质量更大？","options":["铁块","无法比较","一样大","棉花"],"correct_option_index":2,"explanation":"两者都明确标为1千克。"},{"question":"鱼缸里有10条鱼，其中3条死了，但没有被取走。缸里还有几条鱼？","options":["13条","10条","7条","3条"],"correct_option_index":1,"explanation":"死亡不会让鱼凭空消失。"},{"question":"一列完全使用电力的火车正在行驶，没有其他燃烧设备。烟会往哪个方向飘？","options":["不会产生燃烧烟雾","车头方向","车尾方向","必定向北"],"correct_option_index":0,"explanation":"题目排除了任何会制造燃烧烟雾的来源。"},{"question":"你在比赛中超过原来的第二名，现在通常排第几？","options":["第一名","第三名","最后一名","第二名"],"correct_option_index":3,"explanation":"超过第二名只是占据第二的位置，并没有超过第一名。"},{"question":"一个房间有4个角，每个角坐1只猫，房里一共有多少只猫？","options":["12只","16只","4只","8只"],"correct_option_index":2,"explanation":"每个角各一只，合计4只。"},{"question":"3只猫在3分钟内各抓到1只老鼠，假设速度不变，6只猫各抓1只需要多久？","options":["9分钟","3分钟","6分钟","1分钟"],"correct_option_index":1,"explanation":"猫同时独立抓鼠，每只仍花3分钟。"},{"question":"有5个人，每两个人只握手一次，一共有多少次握手？","options":["10次","5次","20次","25次"],"correct_option_index":0,"explanation":"不同两人组合为5×4÷2=10。"},{"question":"星期一再过10整天，会是星期几？","options":["星期三","星期五","星期日","星期四"],"correct_option_index":3,"explanation":"10天相当于1周加3天，星期一后3天是星期四。"},{"question":"时钟刚好显示12:00，分针与时针的夹角是多少？","options":["180度","30度","0度","90度"],"correct_option_index":2,"explanation":"两针在12点正好重叠。"},{"question":"小盒子放入一面镜子，镜子照出两颗糖。若原来盒里只有两颗糖，糖果实体有多少颗？","options":["0颗","2颗","4颗","6颗"],"correct_option_index":1,"explanation":"镜像不会增加真实物体数量。"},{"question":"一条路有6个路灯，相邻两灯距离5米。第一盏到最后一盏有多远？","options":["25米","30米","20米","35米"],"correct_option_index":0,"explanation":"6盏灯之间只有5段间隔。"},{"question":"10本书从左到右排成一排，拿走最左边1本，剩下多少本？","options":["10本","8本","11本","9本"],"correct_option_index":3,"explanation":"直接从10本减去拿走的1本。"},{"question":"一架无人机垂直上升，机上没有指南针。它向上移动是否等于向北移动？","options":["只在晚上是","只在海上是","不是","一定是"],"correct_option_index":2,"explanation":"上下与南北是不同方向。"},{"question":"一个袋子装有红球和蓝球各1个，不看地拿出2个球，会拿到什么组合？","options":["什么也没有","1红1蓝","2红","2蓝"],"correct_option_index":1,"explanation":"袋子总共只有两个不同颜色的球。"},{"question":"两只相同的钟同时走时，其中一只快了3分钟。快钟显示9:03时慢钟显示几点？","options":["9:00","9:06","8:57","9:30"],"correct_option_index":0,"explanation":"两只相差固定3分钟。"},{"question":"书本从第1页到第10页全部按顺序编号，共有多少个页码数字？","options":["10个","20个","9个","11个"],"correct_option_index":3,"explanation":"1至9各1位共9位，10有2位，总11位。"},{"question":"一台机器每秒打印1张纸，三台相同机器同时工作5秒共打印几张？","options":["8张","30张","15张","5张"],"correct_option_index":2,"explanation":"3台×每台每秒1张×5秒=15张。"},{"question":"你有两把完全相同的钥匙，其中只有一把能开门。最坏情况下最多试几把就能确定？","options":["无法确定","2把","1把","3把"],"correct_option_index":1,"explanation":"试第一把不成功，再试第二把即可。"}]},{"id":"c8202611-05c0-4a9b-9f00-000000000002","title":"科学怎么这么怪：反常识挑战","subject":"反常识科学","grade_level":"Year 7","language":"zh","description":"20 道有趣的基础科学反常识题，把想当然变成可验证的知识。","questions":[{"question":"在太空真空中，没有空气传播时，你能直接听到远处爆炸的声音吗？","options":["能而且更响","只能听到回声","声音会加速","不能"],"correct_option_index":3,"explanation":"普通声波需要物质介质才能传播。"},{"question":"把一杯冰水放在温暖室内，杯壁外侧的小水珠主要来自哪里？","options":["冰直接变成雨","杯子制造水","空气中的水蒸气凝结","杯里的水穿过玻璃"],"correct_option_index":2,"explanation":"空气中水蒸气遇冷表面会凝结。"},{"question":"阳光照在一面普通平面镜上，光会怎样？","options":["必定变成声音","大部分按反射规律改变方向","全部被镜子吃掉","完全停止运动"],"correct_option_index":1,"explanation":"平面镜主要反射光线。"},{"question":"戴黑色太阳镜后太阳光是否真的变弱了？","options":["到眼睛的光通常减少","太阳本身突然变暗","地球离太阳更远","太阳被镜片关掉"],"correct_option_index":0,"explanation":"镜片改变进入眼睛的光量，不改变太阳。"},{"question":"两颗质量不同的球在真空里从同一高度同时自由落下，会怎样？","options":["重球必定先落地","轻球必定先落地","都不会动","同时落地"],"correct_option_index":3,"explanation":"忽略其他因素时，自由落体加速度相同。"},{"question":"水在山顶通常比海平面更容易在较低温度沸腾，主要因为？","options":["海拔改变水的元素","山上有更多盐","气压较低","山上水分子变小"],"correct_option_index":2,"explanation":"压力降低使水的沸点下降。"},{"question":"宇航员看起来飘浮，代表他们完全不受地球引力吗？","options":["只因为飞船有风扇","不是，他们与飞船一起持续自由落体","是，引力消失了","是，质量变成零"],"correct_option_index":1,"explanation":"轨道上的失重状态主要与持续自由落体有关。"},{"question":"把一块磁铁切成两小块，通常会出现什么？","options":["两块各有南北磁极","单独一个纯北极","完全没有磁性","只剩电池"],"correct_option_index":0,"explanation":"普通磁体分开后每块仍会有两个磁极。"},{"question":"把冰块放入装满水的杯子后，冰融化会让水面必定大幅升高吗？","options":["必定升高十倍","水变成固体","水全部蒸发","不会，漂浮冰融化通常不改变水面高度"],"correct_option_index":3,"explanation":"漂浮冰排开的水重与融化后的水相等。"},{"question":"如果将盐加入纯水，盐完全溶解后会发生什么？","options":["水变成金属","盐一定沉到底部","形成均匀盐水混合物","盐原子消失"],"correct_option_index":2,"explanation":"盐溶解后以离子形式分散在水中。"},{"question":"热气球能够上升，最直接的原因是？","options":["云朵牵引","球内热空气整体密度比外面空气低","空气变得没有重力","地面磁铁推着球"],"correct_option_index":1,"explanation":"温差造成的密度差产生净浮力。"},{"question":"普通玻璃杯里的铅笔浸在水中看起来折弯了，主要原因？","options":["光的折射","铅笔真的折断","杯子发出电磁波","空气停止流动"],"correct_option_index":0,"explanation":"光在空气与水交界面改变传播方向。"},{"question":"当月亮呈现满月，是否意味着它自己发出可见光？","options":["是，像灯泡发电","是，火山持续发光","月亮完全透明","不是，主要反射太阳光"],"correct_option_index":3,"explanation":"满月亮光主要是太阳光反射。"},{"question":"红色衣服在白光下呈红色，主要由于它？","options":["吸收全部红光","把蓝光变成水","反射较多红色波段的光","创造红色光子"],"correct_option_index":2,"explanation":"物体颜色与吸收和反射的光谱有关。"},{"question":"你把金属勺与木勺放在同一室温一晚后摸起来金属更凉，为什么？","options":["金属没有温度","金属传热更快","金属必定温度更低","木勺会自己发热"],"correct_option_index":1,"explanation":"触感受热传导速率影响很大。"},{"question":"想看清细胞内的细节，哪种工具通常比肉眼更合适？","options":["显微镜","指南针","听诊器","温度计"],"correct_option_index":0,"explanation":"显微镜能放大微小结构。"},{"question":"同样的声音在空气和真空中传播，正确的说法是？","options":["真空中传播更快","真空中回声更响","空气让声音消失","真空中不能靠普通声波传播"],"correct_option_index":3,"explanation":"声波需要介质，真空不支持普通声音传播。"},{"question":"一台风扇朝你吹风，为什么常会觉得更凉？","options":["空气没有质量","风扇让体温自动归零","空气流动加速皮肤散热及汗液蒸发","风扇直接制造冷量"],"correct_option_index":2,"explanation":"气流增强对流和蒸发散热。"},{"question":"把一张纸揉成团再放开，纸团的总质量在没有碎屑丢失时怎样？","options":["必定变成两倍","基本不变","突然变成零","必定增加十倍"],"correct_option_index":1,"explanation":"改变形状并不会创造或消灭纸的物质。"},{"question":"如果让手电筒光照射墙壁，再用手挡在中间，为什么墙上出现影子？","options":["部分光被手遮挡","手把光染成黑色","墙壁吸收所有空气","手掌产生黑光"],"correct_option_index":0,"explanation":"不透明物体阻挡光传播会形成阴影。"}]},{"id":"c8202611-05c0-4a9b-9f00-000000000003","title":"怪兽数学餐厅：荒诞但算得清","subject":"搞怪数学","grade_level":"Year 6","language":"zh","description":"20 道幽默情境的准确数学题：怪兽、飞碟、披萨与魔法商店。","questions":[{"question":"三头怪兽每头戴4顶帽子，总共有几顶帽子？","options":["9顶","16顶","12顶","7顶"],"correct_option_index":2,"explanation":"按题意列式计算，3×4=12。"},{"question":"外星人买6杯月球奶茶，每杯RM5，需要付多少钱？","options":["RM36","RM30","RM11","RM25"],"correct_option_index":1,"explanation":"按题意列式计算，6×5=30。"},{"question":"一条龙有18颗糖，平均分给3只小恐龙，每只几颗？","options":["6颗","9颗","3颗","15颗"],"correct_option_index":0,"explanation":"按题意列式计算，18÷3=6。"},{"question":"飞碟每秒移动7米，5秒移动多少米？","options":["12米","42米","28米","35米"],"correct_option_index":3,"explanation":"按题意列式计算，7×5=35。"},{"question":"魔法商店有48支羽毛笔，卖出19支，还剩多少支？","options":["27支","39支","29支","31支"],"correct_option_index":2,"explanation":"按题意列式计算，48−19=29。"},{"question":"机器人用2分钟叠8件衣服，同样速度10分钟叠几件？","options":["20件","40件","16件","80件"],"correct_option_index":1,"explanation":"每分钟4件，10分钟40件。"},{"question":"吸血鬼买一块RM80的披风，打七五折（付原价75%），应付多少？","options":["RM60","RM20","RM75","RM65"],"correct_option_index":0,"explanation":"80×0.75=60。"},{"question":"史莱姆一开始重4千克，分裂成两个相同质量的小史莱姆，每个重多少？","options":["4千克","8千克","1千克","2千克"],"correct_option_index":3,"explanation":"假设没有质量流失，平均分为两份。"},{"question":"幽灵电影院有7排座椅，每排12个座位，总座位数？","options":["72个","96个","84个","19个"],"correct_option_index":2,"explanation":"按题意列式计算，7×12=84。"},{"question":"小怪兽有100枚金币，买了3件每件17枚金币的衣服，还剩多少？","options":["39枚","49枚","51枚","47枚"],"correct_option_index":1,"explanation":"总花费51枚，100−51=49。"},{"question":"魔法火锅里有36颗丸子，6个锅平均分，每锅几颗？","options":["6颗","8颗","5颗","12颗"],"correct_option_index":0,"explanation":"按题意列式计算，36÷6=6。"},{"question":"一架UFO绕操场飞4圈，每圈400米，总路程？","options":["1000米","800米","2000米","1600米"],"correct_option_index":3,"explanation":"4×400=1600。"},{"question":"忍者猫每3分钟吃1块饼干，连续吃15分钟共吃几块？","options":["6块","15块","5块","3块"],"correct_option_index":2,"explanation":"在每满3分钟吃1块的设定下，15÷3=5。"},{"question":"神秘盒每个装9颗星星贴纸，11个盒子共有多少颗？","options":["89颗","99颗","90颗","101颗"],"correct_option_index":1,"explanation":"按题意列式计算，9×11=99。"},{"question":"魔法师的长袍价格RM120，优惠20%，节省多少钱？","options":["RM24","RM20","RM96","RM30"],"correct_option_index":0,"explanation":"120×20%=24。"},{"question":"章鱼画家有8只腕，每只拿1支画笔，共拿几支？","options":["16支","4支","12支","8支"],"correct_option_index":3,"explanation":"每只腕1支，一共8支。"},{"question":"幽灵电梯从2楼上升5层，抵达哪一楼？","options":["6楼","10楼","7楼","5楼"],"correct_option_index":2,"explanation":"按题意列式计算，2+5=7。"},{"question":"两只机器人各造15个积木，合并后拿走8个，剩多少？","options":["38个","22个","30个","15个"],"correct_option_index":1,"explanation":"2×15−8=22。"},{"question":"独角兽绕圆形草地走一圈，若直径是10米，取圆周率3.14，约走多远？","options":["31.4米","20米","15.7米","314米"],"correct_option_index":0,"explanation":"周长=圆周率×直径=31.4米。"},{"question":"外星汉堡店每份卖RM12，进货成本RM7，卖出10份的毛利是多少（不计其他成本）？","options":["RM70","RM120","RM190","RM50"],"correct_option_index":3,"explanation":"每份毛利RM5，10份共RM50。"}]},{"id":"c8202611-05c0-4a9b-9f00-000000000004","title":"外星人密码本：怪逻辑训练","subject":"外星逻辑","grade_level":"Year 7","language":"zh","description":"20 道有明确定义规则的外星密码题，训练规律、条件和演绎。","questions":[{"question":"火星规则：每个数字都加3。地球数字5变成什么？","options":["53","8","2","15"],"correct_option_index":1,"explanation":"按题意列式计算，按规则5+3=8。"},{"question":"水星规则：每个数乘2再减1。输入4，输出多少？","options":["7","8","6","9"],"correct_option_index":0,"explanation":"按题意列式计算，4×2−1=7。"},{"question":"月球密码把字母A变B、B变C，C会变成哪个字母？","options":["B","E","A","D"],"correct_option_index":3,"explanation":"每个字母向后移动一个位置。"},{"question":"机器人说“噜”代表红色，“啦”代表蓝色。它说“啦”，颜色是什么？","options":["绿色","黄色","蓝色","红色"],"correct_option_index":2,"explanation":"题目已明确定义“啦”的意思。"},{"question":"外星门的密码必须是偶数，以下哪个符合？","options":["49","24","17","35"],"correct_option_index":1,"explanation":"按题意列式计算，24可被2整除。"},{"question":"飞船楼层编号依次为2、4、8、16，下一个按每次乘2是多少？","options":["32","20","24","18"],"correct_option_index":0,"explanation":"每个数是前一个的两倍。"},{"question":"如果火星语“ZOR”代表3，“MIP”代表5，那么“ZOR+MIP”代表的数值和是？","options":["15","2","35","8"],"correct_option_index":3,"explanation":"按题意列式计算，3+5=8。"},{"question":"密码由前三位数字1、2、3按顺序组成，下一位每次加1，应是？","options":["6","0","4","1"],"correct_option_index":2,"explanation":"按连续整数规律，3之后是4。"},{"question":"外星电梯只停3的倍数楼层，下面哪个可以停？","options":["25楼","21楼","20楼","22楼"],"correct_option_index":1,"explanation":"21÷3=7，为整数。"},{"question":"规则“圆圈=2分，三角形=3分”，两个圆圈和一个三角形共几分？","options":["7分","5分","8分","9分"],"correct_option_index":0,"explanation":"按题意列式计算，2×2+3=7。"},{"question":"某机器把输入数字减2再平方。输入5，结果是？","options":["23","25","7","9"],"correct_option_index":3,"explanation":"按题意列式计算，(5−2)²=9。"},{"question":"外星日历一周只有5天，从第一天再过7天（以第一天为0），是第几天？","options":["第4天","第5天","第3天","第2天"],"correct_option_index":2,"explanation":"7除以5余2，所以第一天向后移两天是第三天。"},{"question":"机器人只会在两个按钮都亮时开门。按钮A亮、B不亮，会怎样？","options":["永远损坏","不开门","开门","随机爆炸"],"correct_option_index":1,"explanation":"AND条件要求A与B同时为真。"},{"question":"机器人在任一按钮亮时开门。A不亮、B亮，会怎样？","options":["开门","不开门","只亮灯","无法判断"],"correct_option_index":0,"explanation":"OR条件只需至少一个为真。"},{"question":"飞船名字按字母顺序A、C、E、G排列，下一个应是？","options":["H","J","K","I"],"correct_option_index":3,"explanation":"每次向后跳过一个英文字母。"},{"question":"密码检查器规定长度恰好为4的字符串才通过。哪个能通过？","options":["SPACE","STARSHIP","MOON","SUN"],"correct_option_index":2,"explanation":"MOON有4个字母。"},{"question":"三个星球按大小排序：A比B大，B比C大。最大的是？","options":["三者一样","A","B","C"],"correct_option_index":1,"explanation":"由传递关系A>B>C。"},{"question":"机器人将“猫”编码为7、“狗”编码为9。这两个编码相加是多少？","options":["16","79","2","63"],"correct_option_index":0,"explanation":"7+9=16，题目只要求数值相加。"},{"question":"一颗星星标记代表4点，两个星星标记再加1点是多少？","options":["8点","10点","5点","9点"],"correct_option_index":3,"explanation":"按题意列式计算，4+4+1=9。"},{"question":"两台机器只在信号相同时显示OK。信号分别为0和1，结果是？","options":["显示两个OK","随机选择","不显示OK","显示OK"],"correct_option_index":2,"explanation":"两个信号不同，不符合相同条件。"}]},{"id":"c8202611-05c0-4a9b-9f00-000000000005","title":"Animals That Sound Made Up","subject":"Weird Animals","grade_level":"Year 7","language":"en","description":"20 genuinely strange animal facts, explained without myths or exaggeration.","questions":[{"question":"How many hearts does a typical octopus have?","options":["Three","One","Seven","Zero"],"correct_option_index":0,"explanation":"Octopuses have two hearts serving the gills and one pumping blood through the body."},{"question":"Why can an octopus''s blood look blue?","options":["It drinks blue seawater","It contains blue ink","Its blood has no oxygen carrier","It uses copper-containing hemocyanin"],"correct_option_index":3,"explanation":"Hemocyanin uses copper in oxygen transport, giving the blood a blue appearance."},{"question":"Which animal is a mammal that lays eggs?","options":["Tiger","Bat","Platypus","Dolphin"],"correct_option_index":2,"explanation":"Platypuses are monotremes, a small group of egg-laying mammals."},{"question":"In seahorses, which parent typically carries developing young in a brood pouch?","options":["Neither parent","Male","Female","Both in the same shared pouch"],"correct_option_index":1,"explanation":"Male seahorses carry embryos in a specialised brood pouch."},{"question":"Why are many flamingos pink?","options":["Pigments obtained through their diet","Their bones glow pink","They produce pink light","They paint their feathers"],"correct_option_index":0,"explanation":"Carotenoid pigments from food influence their feather colour."},{"question":"What are a pangolin''s protective scales mostly made of?","options":["Glass","Calcium carbonate crystals only","Metal","Keratin"],"correct_option_index":3,"explanation":"Pangolin scales consist of keratin, a protein also found in hair and nails."},{"question":"Which body part do butterflies use to sense some tastes?","options":["Antennae only","Eyes only","Feet","Wings only"],"correct_option_index":2,"explanation":"Taste receptors on butterfly feet help detect suitable plants."},{"question":"What is unusual about a starfish or sea star''s usual movement?","options":["It jumps using springs","It uses many tiny tube feet","It flies using feathers","It has rolling wheels"],"correct_option_index":1,"explanation":"Sea stars use a water vascular system and tube feet for movement."},{"question":"What feature helps a gecko grip many smooth surfaces?","options":["Tiny specialised structures on its toe pads","Permanent glue on its claws","Magnetic shoes","Electric suction motors"],"correct_option_index":0,"explanation":"Microscopic structures on gecko toes enable strong contact with surfaces."},{"question":"What is a narwhal''s famous long tusk actually?","options":["A horn made of bone alone","A branch stuck to its head","A second tail","An elongated tooth"],"correct_option_index":3,"explanation":"A narwhal tusk develops from a specialised tooth."},{"question":"Which bird is famous for running fast but cannot fly?","options":["Hummingbird","Albatross","Ostrich","Penguin"],"correct_option_index":2,"explanation":"Ostriches are large flightless birds capable of rapid running."},{"question":"What helps many chameleons see in different directions at once?","options":["Transparent bones","Eyes that move largely independently","A second head","Mirrors attached to ears"],"correct_option_index":1,"explanation":"Many chameleons can move their eyes independently to survey surroundings."},{"question":"What is an axolotl widely known for?","options":["Regenerating some lost body parts","Breathing fire","Turning into a bird","Producing electricity like a battery"],"correct_option_index":0,"explanation":"Axolotls can regenerate limbs and other tissues."},{"question":"What is a tardigrade?","options":["A newly discovered moon","A type of tropical tree","A giant carnivorous bird","A tiny eight-legged invertebrate"],"correct_option_index":3,"explanation":"Tardigrades are microscopic animals also called water bears."},{"question":"Why are coral reefs built partly by animals?","options":["Fish weld metal","Crabs manufacture plastic","Coral polyps secrete calcium carbonate skeletons","Whales arrange stones"],"correct_option_index":2,"explanation":"Many reef-building corals make hard skeletons over time."},{"question":"Which mammal is capable of sustained true flight?","options":["Koala","Bat","Flying squirrel","Sugar glider"],"correct_option_index":1,"explanation":"Bats can fly using powered wing strokes; gliding mammals cannot sustain powered flight."},{"question":"How do many cuttlefish rapidly alter their visible colours?","options":["They control pigment-containing skin cells","They swap entire skins every second","They spray coloured seawater onto themselves","Their bones contain LED lights"],"correct_option_index":0,"explanation":"Chromatophores and other skin structures help change appearance."},{"question":"Which creature is a close relative of the octopus?","options":["Jellyfish","Sea turtle","Sea urchin","Squid"],"correct_option_index":3,"explanation":"Octopuses and squids are cephalopod molluscs."},{"question":"What do many bees communicate with a waggle dance?","options":["Their age in human years","Which flower has the loudest sound","Information about a food source''s direction and distance","Tomorrow''s exact weather"],"correct_option_index":2,"explanation":"Honeybee dances can convey spatial information about food."},{"question":"Why is a sloth''s fur sometimes greenish?","options":["Its skin emits green light","Algae may grow on its fur","It is made entirely of leaves","Sloths are actually plants"],"correct_option_index":1,"explanation":"Algae living in sloth fur can contribute to a greenish tint."}]},{"id":"c8202611-05c0-4a9b-9f00-000000000006","title":"Space Has No Chill: Strange Solar System","subject":"Strange Space","grade_level":"Year 7","language":"en","description":"20 surprising but grounded space facts, including bizarre rotation and impossible vacations.","questions":[{"question":"Which planet''s rotation period is longer than its year around the Sun?","options":["Earth","Mars","Jupiter","Venus"],"correct_option_index":3,"explanation":"Venus takes about 243 Earth days to rotate once and about 225 days to orbit."},{"question":"On which planet would the Sun appear to rise in the west due to retrograde rotation?","options":["Earth","Mercury","Venus","Mars"],"correct_option_index":2,"explanation":"Venus rotates opposite the direction typical of most planets."},{"question":"Which planet appears to roll on its side because of its extreme axial tilt?","options":["Mercury","Uranus","Venus","Earth"],"correct_option_index":1,"explanation":"Uranus has an axial tilt near 90 degrees."},{"question":"In a scale-model museum, which Solar System planet needs the largest sphere?","options":["Jupiter","Earth","Venus","Mars"],"correct_option_index":0,"explanation":"Jupiter has the largest diameter and mass among the planets."},{"question":"Why can astronauts float inside a spacecraft orbiting Earth?","options":["Earth''s gravity completely disappears","They have no mass","Spacecraft generate magical anti-gravity","They and the spacecraft are in continuous free fall"],"correct_option_index":3,"explanation":"An orbit is a form of continuous free fall."},{"question":"Could you safely stand on the Sun''s visible surface like solid ground?","options":["Yes, because it is made of rock","Yes, only at night","No, it is hot plasma without a solid surface","Yes, with ordinary shoes"],"correct_option_index":2,"explanation":"The Sun is a star composed mainly of extremely hot gas and plasma."},{"question":"Which object is Earth''s natural satellite?","options":["The Sun","The Moon","Mars","Venus"],"correct_option_index":1,"explanation":"The Moon is Earth''s natural satellite."},{"question":"What is an asteroid?","options":["A small rocky or metallic Solar System body","A new type of cloud","A black hole inside Earth","A man-made satellite only"],"correct_option_index":0,"explanation":"Asteroids are smaller bodies orbiting the Sun, often rocky."},{"question":"How does sunlight reach Earth through the vacuum of space?","options":["By sound waves carried through vacuum","By ocean currents","Through a rope from the Sun","As electromagnetic radiation"],"correct_option_index":3,"explanation":"Light travels through vacuum as electromagnetic waves."},{"question":"Why do stars appear to twinkle when viewed from Earth?","options":["They shake Earth''s ground","Their colour disappears every second","Our atmosphere bends their light unevenly","They repeatedly turn off and on"],"correct_option_index":2,"explanation":"Atmospheric turbulence changes the path of starlight."},{"question":"Why might a person weigh less on the Moon than on Earth?","options":["Space suits contain weight-removing magnets","The Moon''s gravitational pull at its surface is weaker","The person''s mass disappears","The Moon has no gravity"],"correct_option_index":1,"explanation":"Weight depends on local gravity, but mass remains nearly the same."},{"question":"What causes the phases of the Moon?","options":["We see differing portions of its sunlit half","Earth changes the Moon''s shape","The Moon turns its lamp on and off","Moon rocks change colour weekly"],"correct_option_index":0,"explanation":"Lunar phase depends on Sun-Moon-Earth geometry."},{"question":"Why does a comet often develop a tail near the Sun?","options":["It is a rocket with a permanent exhaust","It catches fire like wood","It leaves ink in space","Solar heating releases gas and dust pushed away by sunlight and solar wind"],"correct_option_index":3,"explanation":"Heat-driven outgassing creates a coma and tails."},{"question":"Which planet is known for a prominent system of icy rings?","options":["Earth","Mars","Saturn","Mercury"],"correct_option_index":2,"explanation":"Saturn''s rings contain abundant ice particles."},{"question":"Where is the main asteroid belt located?","options":["Beyond the observable universe","Between Mars and Jupiter","Between Earth and the Moon","Inside the Sun"],"correct_option_index":1,"explanation":"The main belt occupies orbits between Mars and Jupiter."},{"question":"What is a light-year?","options":["A distance travelled by light in one year","A type of calendar month","A single day on Venus","The age of all stars"],"correct_option_index":0,"explanation":"A light-year is a unit of distance, not time."},{"question":"Why is Mars often called the Red Planet?","options":["Its seas are filled with red paint","It reflects only radio waves","Every rock there is hot lava","Iron-rich dust and minerals give it a reddish appearance"],"correct_option_index":3,"explanation":"Iron oxide contributes to Mars''s colour."},{"question":"How many Sun-like stars are at the centre of our Solar System?","options":["Eight","None","One","Two"],"correct_option_index":2,"explanation":"Our planetary system orbits one star, the Sun."},{"question":"Why is space not completely empty even far from Earth?","options":["All galaxies have identical density","Sparse particles and radiation can still exist","Every region contains breathable air","Space is filled with liquid water everywhere"],"correct_option_index":1,"explanation":"Interplanetary and interstellar space contain thin matter and radiation."},{"question":"What would an ordinary unprotected human hear from a distant explosion in the vacuum of space?","options":["No sound transmitted through vacuum","A louder bang than on Earth","A low rumble travelling faster than light","Only an echo from the Moon"],"correct_option_index":0,"explanation":"Sound needs a material medium to carry pressure waves."}]},{"id":"c8202611-05c0-4a9b-9f00-000000000007","title":"Impossible Physics: What If...? ","subject":"Physics What-Ifs","grade_level":"Year 7","language":"en","description":"20 absurd imaginary experiments with real scientific reasoning and clearly stated assumptions.","questions":[{"question":"If you drop a hammer and a feather together in a perfect vacuum, which hits first from the same height?","options":["The feather","Neither object falls","They land together","The hammer"],"correct_option_index":2,"explanation":"In a vacuum both have the same free-fall acceleration."},{"question":"If Earth suddenly had no atmosphere, could ordinary speech travel through open air?","options":["Only speech in English","No","Yes, at exactly the same speed","Only whispered speech"],"correct_option_index":1,"explanation":"Sound pressure waves require a medium."},{"question":"If you place a working magnet near a plastic spoon, what should happen in normal conditions?","options":["The spoon is not strongly attracted like iron","It always flies to the magnet","It turns into steel","It starts glowing"],"correct_option_index":0,"explanation":"Most ordinary plastics are not ferromagnetic."},{"question":"A sealed transparent jar contains a plant. Can the plant receive light through the glass?","options":["No, all glass blocks visible light","Only if the jar is blue","Only at midnight","Yes, if the glass transmits that light"],"correct_option_index":3,"explanation":"Ordinary transparent glass lets much visible light through."},{"question":"You place an object in a mirror''s reflection. Does the reflected object have real physical mass behind the mirror?","options":["Twice the object''s mass","It depends on the time","No","Yes, equal to the object''s mass"],"correct_option_index":2,"explanation":"A mirror image is a virtual image, not a physical duplicate."},{"question":"If a submarine dives deeper, what generally happens to the surrounding water pressure?","options":["It changes to air pressure only","It increases","It goes to zero","It always decreases"],"correct_option_index":1,"explanation":"Hydrostatic pressure generally rises with depth."},{"question":"Why does a helium-filled balloon tend to rise in ordinary air?","options":["Its total average density is lower than displaced air","Helium has no mass","Air has no gravity","The balloon is secretly a rocket"],"correct_option_index":0,"explanation":"Buoyancy exceeds the total weight of a light balloon."},{"question":"Could an ordinary flashlight beam be heard as a spoken sentence in vacuum by itself?","options":["Yes, because light is sound","Yes, if the beam is red","Only if you travel faster than it","No"],"correct_option_index":3,"explanation":"Electromagnetic radiation and sound waves are different phenomena."},{"question":"If you put an ice cube in a glass of pure water, what usually happens first?","options":["The ice disappears instantly","The ice turns into salt","The ice floats","The ice sinks like steel"],"correct_option_index":2,"explanation":"Ice is usually less dense than liquid water."},{"question":"If you break a bar magnet in half, how many separate magnetic poles does each ordinary fragment have?","options":["No poles in every case","A north and a south pole","Only a north pole","Only a south pole"],"correct_option_index":1,"explanation":"Breaking a conventional magnet produces smaller dipoles."},{"question":"If you push a wheeled cart on a smoother floor with the same force, friction is usually...?","options":["Lower","Always higher","Exactly infinite","Unrelated to contact surfaces"],"correct_option_index":0,"explanation":"Less friction typically opposes motion on smoother matched surfaces."},{"question":"What happens to a shadow when an opaque object blocks a beam of light?","options":["The object converts light into liquid","Light turns into gravity","All surfaces turn black permanently","A darker region appears behind it"],"correct_option_index":3,"explanation":"An object prevents some light from reaching the surface."},{"question":"If you put a hot metal spoon into cooler water, which way does heat naturally flow at first?","options":["No heat can transfer","From the spoon directly into sunlight","From the spoon toward the water","From the cooler water into the hotter spoon only"],"correct_option_index":2,"explanation":"Heat transfer occurs from higher to lower temperature."},{"question":"If a rubber band stretches, where is energy stored while it is held stretched?","options":["Only chemical fuel","Elastic potential energy","Only nuclear energy","Nothing stores energy"],"correct_option_index":1,"explanation":"Deformation stores recoverable elastic energy."},{"question":"Why can a prism split white light into colours?","options":["Different wavelengths refract by different amounts","Light has tiny paint droplets","The prism generates new colours from nothing","White light contains no wavelengths"],"correct_option_index":0,"explanation":"Dispersion separates light wavelengths due to different refractive indices."},{"question":"An astronaut takes off their boots while orbiting. Does their body stop having mass?","options":["Yes","Only if shoes are white","Only during sleep","No"],"correct_option_index":3,"explanation":"Mass is intrinsic; weightlessness does not remove mass."},{"question":"In a vacuum chamber, an electric bell visibly vibrates. What does a person outside hear through the chamber walls if well isolated acoustically?","options":["The bell speaks a language","A sound that travels without matter","Little or no sound from the vibrating bell through vacuum","A louder bell than in air"],"correct_option_index":2,"explanation":"Ordinary sound cannot cross vacuum; structure-borne leakage depends on isolation."},{"question":"Would a solar panel generate its usual electrical output in complete darkness with no other illumination?","options":["Only on cloudy days","No","Yes, at full power","Yes, because it stores infinite sunlight"],"correct_option_index":1,"explanation":"Photovoltaic panels need incident light to generate power."},{"question":"If you double the time a constant-speed robot moves while keeping its speed unchanged, its travel distance...?","options":["Doubles","Halves","Becomes zero","Stays identical"],"correct_option_index":0,"explanation":"Distance equals speed times time."},{"question":"If you use a perfect balance to compare 2 kg of sand and 2 kg of marshmallows, which has greater mass?","options":["The marshmallows","The sand","The lighter-looking one","Neither; masses are equal"],"correct_option_index":3,"explanation":"Both samples have a mass of 2 kg."}]},{"id":"c8202611-05c0-4a9b-9f00-000000000008","title":"Ridiculous Inventions, Sensible Engineering","subject":"Wacky Inventions","grade_level":"Year 7","language":"en","description":"20 comically odd inventions that teach practical engineering trade-offs and safety.","questions":[{"question":"You invent a hat that catches rainwater. What should you consider first?","options":["How to promise it cures disease","Whether collected water is clean and safe","How to make it weigh 50 kg","How to hide its weight from wearers"],"correct_option_index":1,"explanation":"Collected rainwater can be contaminated and needs proper treatment before drinking."},{"question":"A robot spoon keeps spilling soup. Which design improvement is most useful?","options":["Add a steadier gripping and motion control system","Make the spoon invisible","Remove all sensors","Increase motion speed without testing"],"correct_option_index":0,"explanation":"Controlled movements can reduce spills."},{"question":"Your shoes have tiny fans. Which factor limits how long they can run?","options":["The colour of the laces","The wearer''s favourite number","The day of the week","Available battery energy"],"correct_option_index":3,"explanation":"Powered fans need an energy source."},{"question":"A backpack automatically lights up at night. Which sensor could help?","options":["A compass that measures weight","A ruler","Ambient light sensor","Only a thermometer"],"correct_option_index":2,"explanation":"A light sensor detects low illumination."},{"question":"A smart umbrella keeps opening in strong wind. What design challenge matters?","options":["How many stickers fit on a handle","Wind loads on its frame and hinges","The number of emojis on it","Whether it has a catchy name"],"correct_option_index":1,"explanation":"Wind produces forces that can damage an umbrella."},{"question":"You invent a quiet alarm for a deaf user. Which alternative output could help?","options":["A strong vibration or flashing visual signal","Only a very soft sound","A hidden audio recording","A message in invisible ink"],"correct_option_index":0,"explanation":"Multimodal alerts improve accessibility."},{"question":"A solar-powered toy works only in sunlight. What is a practical way to use it after dark?","options":["Paint the toy yellow","Remove its solar panel","Cover its battery compartment","Add a rechargeable energy store"],"correct_option_index":3,"explanation":"Stored electrical energy can power the toy when illumination is absent."},{"question":"An automatic pencil sharpener jams when a pencil is crooked. What could improve reliability?","options":["Remove all safety stops","Force users to push harder","Guide the pencil into the correct position","Use weaker materials without testing"],"correct_option_index":2,"explanation":"Alignment and protective stops can prevent jams."},{"question":"You invent a floating chair for a swimming pool. What must be tested?","options":["How many hashtags it gets","Buoyancy, stability and user safety","Only its colour","Whether it has music"],"correct_option_index":1,"explanation":"Water devices need stability and safety checks."},{"question":"A robot planter waters crops every hour even when soil is wet. What should you add?","options":["Soil moisture sensing and threshold logic","A louder speaker","Random watering times only","More decorative wheels"],"correct_option_index":0,"explanation":"Sensors can reduce unnecessary irrigation."},{"question":"An absurd giant straw is 20 metres long. What may make drinking through it difficult?","options":["The colour of the straw","Whether it has stripes","The person''s hairstyle","Pressure differences and fluid resistance"],"correct_option_index":3,"explanation":"A long tube increases resistance and may exceed practical suction limits."},{"question":"A bicycle helmet is designed like a pineapple. What matters more than its appearance?","options":["Adding the tallest decorative leaf","Increasing weight as much as possible","Impact protection and proper fit","Matching the bicycle colour exactly"],"correct_option_index":2,"explanation":"Helmet safety depends on certified protection and fit."},{"question":"A phone-controlled toaster accidentally heats while unattended. What safety feature is important?","options":["Making the heating element exposed","Automatic shutoff and temperature limits","More notification sounds only","Removing the power indicator"],"correct_option_index":1,"explanation":"Fail-safe shutdown reduces fire risk."},{"question":"Your robotic pencil case keeps opening in a bag. Which sensor or mechanism helps?","options":["A secure latch with intentional opening control","An always-on motor","Loose hinges","A bigger logo"],"correct_option_index":0,"explanation":"A latch prevents accidental opening."},{"question":"An elevator can play music but its emergency button is hidden. What is the highest-priority fix?","options":["Add more songs","Change the background wallpaper","Increase speaker volume","Make emergency controls accessible and visible"],"correct_option_index":3,"explanation":"Safety controls outrank entertainment features."},{"question":"An AI-powered fridge guesses every meal incorrectly. How should the team improve it?","options":["Delete all error reports","Ask users for passwords","Test real needs and correct unreliable assumptions","Claim 100% accuracy anyway"],"correct_option_index":2,"explanation":"Feedback and measurable testing support improvement."},{"question":"A paper bridge collapses under a stack of books. What should you do?","options":["Increase the stack without analysis","Test stronger folds and load paths","Keep using the same shape without change","Hide the collapse"],"correct_option_index":1,"explanation":"Fold geometry can improve strength and load distribution."},{"question":"An umbrella follows its owner using GPS but collides with people. Which capability is missing?","options":["Reliable local obstacle detection and avoidance","A longer product name","More decorative colours","A louder motor only"],"correct_option_index":0,"explanation":"GPS alone does not detect nearby moving obstacles."},{"question":"A classroom scoreboard updates slowly on bad Wi-Fi. What design helps?","options":["Infinite retries without limits","Hiding all error messages","Requiring users to click 100 times","Graceful offline/error states and recovery"],"correct_option_index":3,"explanation":"Explicit recovery and bounded retry improve reliability."},{"question":"A robot cat has ten blinking lights but no privacy policy. What should a responsible designer prioritise?","options":["Collect all nearby contacts silently","Store plaintext passwords","Explain data collection and protect user information","Make lights blink faster"],"correct_option_index":2,"explanation":"Privacy and security are essential even for playful devices."}]},{"id":"c8202611-05c0-4a9b-9f00-000000000009","title":"Detective Duck: Tiny Mysteries with Clues","subject":"Funny Mysteries","grade_level":"Year 7","language":"en","description":"20 playful mini-detective mysteries where all clues are given and there is only one correct deduction.","questions":[{"question":"Three pets are a cat, a dog and a rabbit. The rabbit is in the blue room, the dog is in the green room. Who is in the red room?","options":["The cat","The dog","The rabbit","No pet"],"correct_option_index":0,"explanation":"With each pet assigned a different room, the remaining cat is in red."},{"question":"Mira, Leo and Nia own red, green and blue umbrellas. Mira has red, Leo does not have blue. Which colour does Nia have?","options":["Green","Red","Yellow","Blue"],"correct_option_index":3,"explanation":"Leo must have green; Nia gets blue."},{"question":"A thief left muddy footprints, but the floor had been dry and locked all day before a rainstorm. Which event most likely happened after rain began?","options":["The rain fell indoors without an opening","The prints are magnetic","Someone walked inside with wet shoes","The floor cleaned itself"],"correct_option_index":2,"explanation":"Wet muddy prints suggest someone entered after becoming muddy outside."},{"question":"Only one of three boxes contains a coin. Box A is empty and box C is empty. Where is the coin?","options":["No box","Box B","Box A","Box C"],"correct_option_index":1,"explanation":"Only B remains as the possible location."},{"question":"A note says \"the secret is the first letter of CAT\". Which letter is the secret?","options":["C","A","T","D"],"correct_option_index":0,"explanation":"The first letter of CAT is C."},{"question":"A detective''s watch stopped at 14:10. It has not moved since. What does its display show at 18:00?","options":["18:00","14:18","00:00","14:10"],"correct_option_index":3,"explanation":"A stopped watch does not change its display."},{"question":"A robot leaves a room at 09:15 and returns 20 minutes later. When does it return?","options":["09:45","10:15","09:35","09:25"],"correct_option_index":2,"explanation":"15 minutes past 9 plus 20 minutes is 35 minutes past 9."},{"question":"The suspect''s gloves are dry, but a wet glove is found outside. Can you identify the suspect from this fact alone?","options":["Yes; the tallest person","No; more evidence is needed","Yes; definitely the person with a blue shirt","Yes; any person nearby"],"correct_option_index":1,"explanation":"A single glove observation cannot identify its owner conclusively."},{"question":"Three suspects have badges 11, 12 and 13. The clue says the badge number is even. Which badge matches?","options":["12","11","13","All three"],"correct_option_index":0,"explanation":"Only 12 is divisible by two."},{"question":"A museum has four doors. Only the north door was opened in the event log. Which door should investigators examine first for recorded entry?","options":["South door","West door","East door","North door"],"correct_option_index":3,"explanation":"The entry log points to the north door; other evidence may still matter."},{"question":"A parrot repeats exactly the last word it hears. You say \"yellow banana\". What does it repeat?","options":["yellow banana","parrot","banana","yellow"],"correct_option_index":2,"explanation":"By the given rule it repeats only the final word."},{"question":"The code is the number of letters in MOON plus the number in STAR. What is the code?","options":["16","8","7","9"],"correct_option_index":1,"explanation":"MOON has four letters and STAR has four, giving eight."},{"question":"All five biscuits are in a locked tin. Someone takes out two and does not replace them. How many remain in the tin?","options":["3","2","5","7"],"correct_option_index":0,"explanation":"Five minus two leaves three."},{"question":"A detective needs to visit rooms A, B and C once each. She has visited A and B. Which room remains?","options":["A","B","D","C"],"correct_option_index":3,"explanation":"Only room C is unvisited."},{"question":"A password clue says \"a 3-digit code starting 42 and ending 7\". What code fits?","options":["247","4270","427","472"],"correct_option_index":2,"explanation":"The first two digits are 42 and the last is 7."},{"question":"A message was sent at 11:00 and received at 11:02. Assuming clocks are synchronised, how long did delivery take?","options":["20 minutes","2 minutes","1 minute","12 minutes"],"correct_option_index":1,"explanation":"11:02 minus 11:00 is two minutes."},{"question":"If only red cards trigger the alarm, and a blue card was scanned, should the alarm trigger under this rule?","options":["No","Yes","Only on weekends","Only with two blue cards"],"correct_option_index":0,"explanation":"The stated rule triggers on red cards only."},{"question":"A detective compares two identical-sized bottles: one is full and one is half-full. Which contains more liquid?","options":["The half-full bottle","They contain equal liquid","Neither contains liquid","The full bottle"],"correct_option_index":3,"explanation":"Equal capacity with one full means the full one holds more."},{"question":"The laboratory door opens only if both lights are green. One light is green, the other red. What happens?","options":["It disappears","It turns into a window","It stays locked","It opens"],"correct_option_index":2,"explanation":"Both-green condition is not met."},{"question":"A security camera recorded three visitors entering and two exiting, with no other entrances or exits. How many of those visitors remain inside?","options":["5","1","2","3"],"correct_option_index":1,"explanation":"Three entered and two left, leaving one of the recorded visitors."}]},{"id":"c8202611-05c0-4a9b-9f00-000000000010","title":"Everyday Things That Are Surprisingly Weird","subject":"Weird Everyday Science","grade_level":"Year 6","language":"en","description":"20 quirky household phenomena with solid explanations: static hair, soap bubbles, popcorn and more.","questions":[{"question":"Why does popcorn suddenly pop when heated?","options":["The kernel is magnetic","Salt makes it explode by itself","The corn turns into metal","Water inside the kernel becomes pressurised steam"],"correct_option_index":3,"explanation":"Steam pressure builds until the kernel ruptures."},{"question":"Why can a rubbed balloon stick to a wall?","options":["The wall becomes a magnet","Air stops having gravity","Static electric attraction","The balloon creates permanent glue"],"correct_option_index":2,"explanation":"Transferred electric charge can produce attraction."},{"question":"Why do soap bubbles often look rainbow-coloured?","options":["Soap is naturally made of tiny rainbows","Thin-film interference separates reflected light colours","Bubbles contain rainbow paint","Water creates LEDs"],"correct_option_index":1,"explanation":"Light reflecting from a thin film interferes at different wavelengths."},{"question":"Why can wet fingers make a glass surface seem slippery?","options":["A water film changes friction at the contact surface","Water eliminates all forces","Glass becomes soft like butter","The fingers stop having skin"],"correct_option_index":0,"explanation":"Lubrication alters friction between surfaces."},{"question":"Why do onions sometimes make eyes water when cut?","options":["They produce salty tears directly","Onions are radioactive","Their colour blocks vision","They release irritating volatile chemicals"],"correct_option_index":3,"explanation":"Cutting onions releases compounds that irritate the eyes."},{"question":"Why can a metal spoon feel colder than a wooden one in the same room?","options":["Wood creates sunlight","Metal is always below freezing","Metal transfers heat away from skin more quickly","Metal has no temperature"],"correct_option_index":2,"explanation":"Thermal conductivity affects how rapidly skin loses heat."},{"question":"Why does a straw make liquid rise when you sip?","options":["The glass pushes liquid using electricity","Lower pressure inside the straw lets surrounding pressure push liquid up","The straw attracts water magnetically","Your mouth creates gravity"],"correct_option_index":1,"explanation":"Pressure differences drive the liquid upward."},{"question":"Why does a fan often make sweaty skin feel cooler?","options":["It increases evaporation and heat transfer","It turns air into ice","It switches off body heat","It changes Earth''s orbit"],"correct_option_index":0,"explanation":"Moving air speeds evaporation and convection."},{"question":"Why can you see your breath on a chilly morning?","options":["Your lungs make smoke","Oxygen turns into visible metal","Air becomes solid everywhere","Moist breath forms tiny liquid droplets in cool air"],"correct_option_index":3,"explanation":"Cooling water vapour can form a visible mist."},{"question":"Why does an unopened cold soda sometimes fizz when opened?","options":["Sugar turns into fire","The bottle becomes magnetic","Dissolved carbon dioxide escapes as pressure falls","Oxygen always burns the drink"],"correct_option_index":2,"explanation":"Lower pressure allows dissolved gas to form bubbles."},{"question":"Why can ice make a drink float with cubes on top?","options":["Ice is made of air only","Ice is less dense than liquid water","Ice has no mass","The glass pushes it upward magnetically"],"correct_option_index":1,"explanation":"A lower-density solid floats in a denser liquid."},{"question":"Why does cut apple flesh often brown after exposure to air?","options":["Enzymatic reactions involving oxygen","The apple absorbs sunlight as paint","Its sugar turns into iron","The peel changes to metal"],"correct_option_index":0,"explanation":"Polyphenol oxidase contributes to browning reactions."},{"question":"Why do shadows grow longer when a low Sun shines near the horizon?","options":["Objects become taller at sunset","Gravity gets stronger each evening","The ground tilts suddenly","The light arrives at a shallow angle"],"correct_option_index":3,"explanation":"Low-angle sunlight stretches the shadow."},{"question":"Why can a lid on a jar be easier to open after warming it slightly?","options":["The jar turns into rubber","The lid loses all friction","Heating may expand the lid enough to loosen it","Warm water removes gravity"],"correct_option_index":2,"explanation":"Different thermal expansion can help loosen the fit."},{"question":"Why does water form rounded drops on some waxy leaves?","options":["The leaf becomes magnetic","Surface tension and poor wetting of the leaf surface","Leaves generate marbles","Water stops being a liquid"],"correct_option_index":1,"explanation":"Cohesive forces and surface chemistry shape droplets."},{"question":"Why can sugar seem to disappear when stirred into water?","options":["It dissolves and disperses among water molecules","It leaves the universe","It transforms into air automatically","The spoon absorbs all sugar"],"correct_option_index":0,"explanation":"Dissolved sugar remains in the solution."},{"question":"What makes a rubber ball bounce?","options":["It contains a gravity switch","Air always pushes it upward forever","It has a hidden motor in every case","Elastic deformation stores and returns some energy"],"correct_option_index":3,"explanation":"Material elasticity returns some stored energy after impact."},{"question":"Why do mirrors show a reversed-looking image without producing a second person?","options":["They make time flow backward","They project your body behind the wall","They redirect incoming light into a virtual image","They duplicate human bodies"],"correct_option_index":2,"explanation":"Mirror reflections create virtual images from redirected light."},{"question":"Why is a rainbow often seen with the Sun behind the observer?","options":["Rainwater contains coloured dust by default","Water droplets bend, reflect and disperse sunlight toward the viewer","Clouds grow coloured wires","The Sun becomes a laser screen"],"correct_option_index":1,"explanation":"The viewing geometry of sunlight and droplets creates a rainbow."},{"question":"Why does bread dough with yeast often rise?","options":["Yeast produces carbon dioxide that forms bubbles in dough","Flour becomes magnetic","Water transforms into stone","Air pressure vanishes"],"correct_option_index":0,"explanation":"Fermentation can release gas trapped by the dough''s structure."}]},{"id":"c8202611-05c0-4a9b-9f00-000000000011","title":"Teka-Teki Pelik Tapi Logik","subject":"Teka-Teki Pelik","grade_level":"Tahun 6","language":"ms","description":"20 teka-teki lucu dengan satu jawapan yang jelas dan penerangan Bahasa Melayu.","questions":[{"question":"Dalam setahun ada 12 bulan. Berapa bulan mempunyai sekurang-kurangnya 28 hari?","options":["2","6","12","1"],"correct_option_index":2,"explanation":"Semua bulan mempunyai sekurang-kurangnya 28 hari."},{"question":"Ada 5 biji epal di meja. Kamu ambil 3. Berapa biji epal yang ada di tangan kamu?","options":["8","3","2","5"],"correct_option_index":1,"explanation":"Soalan bertanya epal yang diambil, bukan yang masih di atas meja."},{"question":"Yang manakah lebih berat, 1 kg kapas atau 1 kg besi?","options":["Sama berat","Kapas","Besi","Tidak boleh dibandingkan"],"correct_option_index":0,"explanation":"Kedua-duanya berjisim satu kilogram."},{"question":"Seekor robot mempunyai 4 roda. Tiga robot sama mempunyai berapa roda?","options":["7","8","16","12"],"correct_option_index":3,"explanation":"3 darab 4 bersamaan 12 roda."},{"question":"Kamu memotong sebiji piza kepada 4 bahagian sama besar. Berapa bahagian semuanya?","options":["8","1","4","2"],"correct_option_index":2,"explanation":"Bilangan kepingan yang dinyatakan ialah empat."},{"question":"Terdapat 10 ekor ikan di dalam akuarium. Dua mati tetapi tidak dikeluarkan. Berapa ekor masih di dalam akuarium?","options":["12","10","8","2"],"correct_option_index":1,"explanation":"Ikan mati tetap berada dalam akuarium jika tidak dikeluarkan."},{"question":"Jam digital menunjukkan 10:00. Selepas 45 minit, apakah waktunya?","options":["10:45","10:30","11:45","09:45"],"correct_option_index":0,"explanation":"45 minit selepas pukul sepuluh ialah 10:45."},{"question":"Tiga raksasa masing-masing mempunyai dua mata. Jumlah semua mata mereka?","options":["3","9","12","6"],"correct_option_index":3,"explanation":"3 raksasa darab 2 mata bersamaan 6."},{"question":"Jika hari ini hari Isnin, tiga hari kemudian hari apa?","options":["Jumaat","Ahad","Khamis","Rabu"],"correct_option_index":2,"explanation":"Selasa hari pertama, Rabu kedua, Khamis ketiga."},{"question":"Ada 6 pensel. Dua diberi kepada kawan dan satu hilang. Berapa pensel tinggal?","options":["5","3","4","2"],"correct_option_index":1,"explanation":"6 tolak 2 tolak 1 bersamaan 3."},{"question":"Sebuah UFO membawa 7 makhluk asing. Dua turun dan tiga naik. Berapa penumpang sekarang?","options":["8","6","10","12"],"correct_option_index":0,"explanation":"Kiraannya ialah 7−2+3=8."},{"question":"Ada 4 pasang kasut. Berapa kasut individu semuanya?","options":["4","6","12","8"],"correct_option_index":3,"explanation":"Setiap pasang mempunyai dua kasut."},{"question":"Sebuah buku mempunyai 20 halaman. Kamu baca 5 halaman. Berapa halaman belum dibaca?","options":["10","5","15","25"],"correct_option_index":2,"explanation":"20 tolak 5 sama dengan 15."},{"question":"Dua ekor kucing masing-masing makan 3 biskut. Berapa biskut dimakan?","options":["9","6","5","3"],"correct_option_index":1,"explanation":"2 darab 3 bersamaan 6."},{"question":"Kereta elektrik tanpa enjin pembakaran bergerak. Adakah ia mengeluarkan asap ekzos pembakaran seperti kereta petrol?","options":["Tidak","Ya, sentiasa","Hanya pada waktu malam","Hanya ketika hujan"],"correct_option_index":0,"explanation":"Kereta elektrik tanpa sumber pembakaran tidak menghasilkan asap ekzos enjin petrol."},{"question":"Kamu berada di tempat kedua dalam perlumbaan dan memintas peserta pertama. Kamu kini nombor berapa?","options":["Kedua","Ketiga","Terakhir","Pertama"],"correct_option_index":3,"explanation":"Memintas orang pertama menjadikan kamu peserta pertama."},{"question":"Sebiji tembikai dibahagi kepada 8 potongan sama besar. Empat potongan dimakan. Berapa potongan tinggal?","options":["2","6","4","8"],"correct_option_index":2,"explanation":"Kiraannya ialah 8−4=4."},{"question":"Lampu berkelip sekali setiap 2 saat. Dalam 10 saat, jika ia berkelip pada saat 2,4,6,8,10, berapa kali?","options":["10","5","4","6"],"correct_option_index":1,"explanation":"Lima waktu yang disenaraikan menghasilkan lima kelipan."},{"question":"Ada 9 kerusi. Tujuh kerusi diduduki satu orang setiap satu. Berapa kerusi kosong?","options":["2","3","7","9"],"correct_option_index":0,"explanation":"9−7=2 kerusi kosong."},{"question":"Mesin menghasilkan 5 pelekat setiap minit. Berapa pelekat dalam 4 minit?","options":["9","15","25","20"],"correct_option_index":3,"explanation":"5 pelekat seminit darab 4 minit bersamaan 20."}]},{"id":"c8202611-05c0-4a9b-9f00-000000000012","title":"Sains Pelik: Betul atau Mengarut?","subject":"Sains Pelik","grade_level":"Tahun 7","language":"ms","description":"20 soalan sains yang pelik tetapi berdasarkan fenomena sebenar dan logik eksperimen.","questions":[{"question":"Mengapakah sudu logam terasa lebih sejuk daripada sudu kayu pada suhu bilik yang sama?","options":["Logam menghasilkan ais","Logam memindahkan haba daripada tangan lebih cepat","Logam tidak mempunyai suhu","Kayu selalu lebih panas"],"correct_option_index":1,"explanation":"Kekonduksian haba logam lebih tinggi."},{"question":"Mengapa ais biasanya terapung di dalam air?","options":["Ais kurang tumpat daripada air cecair","Ais tidak mempunyai jisim","Ais diperbuat daripada udara","Air ialah magnet"],"correct_option_index":0,"explanation":"Ketumpatan ais lebih rendah berbanding air cecair."},{"question":"Dalam ruang vakum, bolehkah bunyi loceng bergerak terus melalui ruang kosong?","options":["Ya, lebih kuat","Ya, tanpa had","Hanya jika loceng merah","Tidak"],"correct_option_index":3,"explanation":"Gelombang bunyi biasa memerlukan medium untuk merambat."},{"question":"Mengapa pensel dalam gelas air kelihatan bengkok?","options":["Air menukar pensel menjadi getah","Gelas menghasilkan bayang hitam","Pembiasan cahaya","Pensel patah apabila disentuh air"],"correct_option_index":2,"explanation":"Cahaya berubah arah apabila merentasi air dan udara."},{"question":"Apakah yang menyebabkan pelangi terbentuk?","options":["Petir melukis warna","Cahaya matahari dibiaskan, dipantulkan dan diuraikan oleh titisan air","Awan menghasilkan cat","Udara menjadi logam"],"correct_option_index":1,"explanation":"Cahaya berinteraksi dengan titisan air untuk menghasilkan spektrum."},{"question":"Mengapakah belon yang digosok boleh melekat pada dinding?","options":["Tarikan elektrostatik","Belon menghasilkan gam kekal","Dinding menjadi besi","Udara kehilangan graviti"],"correct_option_index":0,"explanation":"Cas elektrik boleh menghasilkan daya tarikan."},{"question":"Mengapa bayang-bayang menjadi panjang apabila matahari rendah?","options":["Objek menjadi semakin tinggi","Graviti bertambah setiap petang","Tanah memanjang","Sudut cahaya matahari lebih rendah"],"correct_option_index":3,"explanation":"Sudut cahaya mempengaruhi panjang bayang."},{"question":"Tumbuhan hijau memerlukan gas manakah untuk fotosintesis?","options":["Nitrogen sahaja","Hidrogen tulen","Karbon dioksida","Helium"],"correct_option_index":2,"explanation":"Tumbuhan mengambil karbon dioksida untuk menghasilkan gula."},{"question":"Apakah fungsi utama akar tumbuhan?","options":["Mencipta cahaya matahari","Menyerap air dan mineral serta membantu menyokong tumbuhan","Menghasilkan bunyi muzik","Membina awan"],"correct_option_index":1,"explanation":"Akar menyerap bahan dari tanah dan memberi sokongan."},{"question":"Mengapakah kita dapat melihat Bulan bersinar?","options":["Bulan memantulkan cahaya matahari","Bulan mempunyai lampu elektrik","Bulan diperbuat daripada api","Bulan menghasilkan semua cahaya sendiri"],"correct_option_index":0,"explanation":"Cahaya Bulan yang kelihatan kebanyakannya ialah pantulan cahaya matahari."},{"question":"Planet manakah mengambil masa putaran paksi lebih lama daripada tempoh orbitnya mengelilingi Matahari?","options":["Bumi","Marikh","Musytari","Zuhrah"],"correct_option_index":3,"explanation":"Zuhrah berputar dalam kira-kira 243 hari Bumi dan mengorbit dalam kira-kira 225 hari."},{"question":"Planet manakah kelihatan berputar mengiring kerana kecondongan paksinya yang sangat besar?","options":["Bumi","Marikh","Uranus","Utarid"],"correct_option_index":2,"explanation":"Paksi Uranus condong hampir 90 darjah."},{"question":"Sotong kurita biasanya mempunyai berapa jantung?","options":["Lapan","Tiga","Satu","Lima"],"correct_option_index":1,"explanation":"Dua jantung mengepam darah ke insang dan satu ke seluruh badan."},{"question":"Mengapa darah sotong kurita boleh kelihatan biru?","options":["Protein hemocyanin mengandungi kuprum","Ia meminum air berwarna biru","Ia tidak mempunyai darah","Insangnya mengeluarkan cat"],"correct_option_index":0,"explanation":"Hemocyanin menggunakan kuprum untuk membawa oksigen."},{"question":"Mengapakah air mendidih pada suhu lebih rendah di gunung tinggi?","options":["Air menjadi unsur lain","Gunung menarik haba keluar sepenuhnya","Air kehilangan molekul","Tekanan udara lebih rendah"],"correct_option_index":3,"explanation":"Tekanan rendah menurunkan suhu didih air."},{"question":"Mengapa udara bergerak daripada kipas sering menyejukkan kulit berpeluh?","options":["Ia menghentikan haba badan","Kipas mengubah orbit Bumi","Ia mempercepat penyejatan dan pemindahan haba","Ia membuat ketulan ais dalam udara"],"correct_option_index":2,"explanation":"Pengaliran udara meningkatkan penyejatan peluh."},{"question":"Apakah yang menyebabkan jagung bertih meletup ketika dipanaskan?","options":["Biji jagung menerima arus elektrik","Tekanan wap air meningkat di dalam biji jagung","Jagung menjadi magnet","Gula bertukar menjadi logam"],"correct_option_index":1,"explanation":"Wap air yang terperangkap meningkatkan tekanan sehingga kulit pecah."},{"question":"Mengapa air gula boleh menjadi jernih selepas dikacau?","options":["Gula larut dan tersebar di dalam air","Gula hilang dari alam semesta","Gula menjadi batu","Sudu menyerap semua gula"],"correct_option_index":0,"explanation":"Molekul gula masih berada dalam larutan."},{"question":"Mengapakah kita dapat melihat wap seperti kabus daripada nafas pada pagi sejuk?","options":["Paru-paru menghasilkan asap kebakaran","Oksigen menjadi besi","Udara menjadi pejal","Wap air dalam nafas terkondensasi menjadi titisan kecil"],"correct_option_index":3,"explanation":"Udara sejuk membolehkan titisan kecil terbentuk."},{"question":"Apakah yang berlaku kepada jisim 2 kg kapas apabila dibandingkan dengan 2 kg batu menggunakan neraca tepat?","options":["Batu lebih berat","Jisimnya menjadi sifar","Kedua-duanya mempunyai jisim yang sama","Kapas lebih berat"],"correct_option_index":2,"explanation":"Kedua-duanya ialah dua kilogram walaupun isipadunya berbeza."}]}]'::jsonb AS packs)
INSERT INTO public.quiz_sets(id,title,subject,grade_level,language,description,status)
SELECT (p.value->>'id')::uuid,p.value->>'title',p.value->>'subject',p.value->>'grade_level',p.value->>'language',p.value->>'description','published'
FROM payload CROSS JOIN LATERAL jsonb_array_elements(payload.packs) AS p(value)
ON CONFLICT (id) DO NOTHING;
WITH payload AS (SELECT '[{"id":"c8202611-05c0-4a9b-9f00-000000000001","title":"脑洞急转弯：认真想就输了？","subject":"脑洞谜题","grade_level":"Year 6","language":"zh","description":"20 道古怪又有标准答案的逻辑谜题，挑战直觉与阅读细节。","questions":[{"question":"一年十二个月中，有几个月至少有28天？","options":["12个月","1个月","2个月","只有闰年才有"],"correct_option_index":0,"explanation":"每个月都至少有28天，不只是二月。"},{"question":"桌上有3个苹果，你拿走2个，现在你手中有几个？","options":["1个","3个","0个","2个"],"correct_option_index":3,"explanation":"题目问手中，不是桌上剩下的数量。"},{"question":"1千克棉花与1千克铁块，哪个质量更大？","options":["铁块","无法比较","一样大","棉花"],"correct_option_index":2,"explanation":"两者都明确标为1千克。"},{"question":"鱼缸里有10条鱼，其中3条死了，但没有被取走。缸里还有几条鱼？","options":["13条","10条","7条","3条"],"correct_option_index":1,"explanation":"死亡不会让鱼凭空消失。"},{"question":"一列完全使用电力的火车正在行驶，没有其他燃烧设备。烟会往哪个方向飘？","options":["不会产生燃烧烟雾","车头方向","车尾方向","必定向北"],"correct_option_index":0,"explanation":"题目排除了任何会制造燃烧烟雾的来源。"},{"question":"你在比赛中超过原来的第二名，现在通常排第几？","options":["第一名","第三名","最后一名","第二名"],"correct_option_index":3,"explanation":"超过第二名只是占据第二的位置，并没有超过第一名。"},{"question":"一个房间有4个角，每个角坐1只猫，房里一共有多少只猫？","options":["12只","16只","4只","8只"],"correct_option_index":2,"explanation":"每个角各一只，合计4只。"},{"question":"3只猫在3分钟内各抓到1只老鼠，假设速度不变，6只猫各抓1只需要多久？","options":["9分钟","3分钟","6分钟","1分钟"],"correct_option_index":1,"explanation":"猫同时独立抓鼠，每只仍花3分钟。"},{"question":"有5个人，每两个人只握手一次，一共有多少次握手？","options":["10次","5次","20次","25次"],"correct_option_index":0,"explanation":"不同两人组合为5×4÷2=10。"},{"question":"星期一再过10整天，会是星期几？","options":["星期三","星期五","星期日","星期四"],"correct_option_index":3,"explanation":"10天相当于1周加3天，星期一后3天是星期四。"},{"question":"时钟刚好显示12:00，分针与时针的夹角是多少？","options":["180度","30度","0度","90度"],"correct_option_index":2,"explanation":"两针在12点正好重叠。"},{"question":"小盒子放入一面镜子，镜子照出两颗糖。若原来盒里只有两颗糖，糖果实体有多少颗？","options":["0颗","2颗","4颗","6颗"],"correct_option_index":1,"explanation":"镜像不会增加真实物体数量。"},{"question":"一条路有6个路灯，相邻两灯距离5米。第一盏到最后一盏有多远？","options":["25米","30米","20米","35米"],"correct_option_index":0,"explanation":"6盏灯之间只有5段间隔。"},{"question":"10本书从左到右排成一排，拿走最左边1本，剩下多少本？","options":["10本","8本","11本","9本"],"correct_option_index":3,"explanation":"直接从10本减去拿走的1本。"},{"question":"一架无人机垂直上升，机上没有指南针。它向上移动是否等于向北移动？","options":["只在晚上是","只在海上是","不是","一定是"],"correct_option_index":2,"explanation":"上下与南北是不同方向。"},{"question":"一个袋子装有红球和蓝球各1个，不看地拿出2个球，会拿到什么组合？","options":["什么也没有","1红1蓝","2红","2蓝"],"correct_option_index":1,"explanation":"袋子总共只有两个不同颜色的球。"},{"question":"两只相同的钟同时走时，其中一只快了3分钟。快钟显示9:03时慢钟显示几点？","options":["9:00","9:06","8:57","9:30"],"correct_option_index":0,"explanation":"两只相差固定3分钟。"},{"question":"书本从第1页到第10页全部按顺序编号，共有多少个页码数字？","options":["10个","20个","9个","11个"],"correct_option_index":3,"explanation":"1至9各1位共9位，10有2位，总11位。"},{"question":"一台机器每秒打印1张纸，三台相同机器同时工作5秒共打印几张？","options":["8张","30张","15张","5张"],"correct_option_index":2,"explanation":"3台×每台每秒1张×5秒=15张。"},{"question":"你有两把完全相同的钥匙，其中只有一把能开门。最坏情况下最多试几把就能确定？","options":["无法确定","2把","1把","3把"],"correct_option_index":1,"explanation":"试第一把不成功，再试第二把即可。"}]},{"id":"c8202611-05c0-4a9b-9f00-000000000002","title":"科学怎么这么怪：反常识挑战","subject":"反常识科学","grade_level":"Year 7","language":"zh","description":"20 道有趣的基础科学反常识题，把想当然变成可验证的知识。","questions":[{"question":"在太空真空中，没有空气传播时，你能直接听到远处爆炸的声音吗？","options":["能而且更响","只能听到回声","声音会加速","不能"],"correct_option_index":3,"explanation":"普通声波需要物质介质才能传播。"},{"question":"把一杯冰水放在温暖室内，杯壁外侧的小水珠主要来自哪里？","options":["冰直接变成雨","杯子制造水","空气中的水蒸气凝结","杯里的水穿过玻璃"],"correct_option_index":2,"explanation":"空气中水蒸气遇冷表面会凝结。"},{"question":"阳光照在一面普通平面镜上，光会怎样？","options":["必定变成声音","大部分按反射规律改变方向","全部被镜子吃掉","完全停止运动"],"correct_option_index":1,"explanation":"平面镜主要反射光线。"},{"question":"戴黑色太阳镜后太阳光是否真的变弱了？","options":["到眼睛的光通常减少","太阳本身突然变暗","地球离太阳更远","太阳被镜片关掉"],"correct_option_index":0,"explanation":"镜片改变进入眼睛的光量，不改变太阳。"},{"question":"两颗质量不同的球在真空里从同一高度同时自由落下，会怎样？","options":["重球必定先落地","轻球必定先落地","都不会动","同时落地"],"correct_option_index":3,"explanation":"忽略其他因素时，自由落体加速度相同。"},{"question":"水在山顶通常比海平面更容易在较低温度沸腾，主要因为？","options":["海拔改变水的元素","山上有更多盐","气压较低","山上水分子变小"],"correct_option_index":2,"explanation":"压力降低使水的沸点下降。"},{"question":"宇航员看起来飘浮，代表他们完全不受地球引力吗？","options":["只因为飞船有风扇","不是，他们与飞船一起持续自由落体","是，引力消失了","是，质量变成零"],"correct_option_index":1,"explanation":"轨道上的失重状态主要与持续自由落体有关。"},{"question":"把一块磁铁切成两小块，通常会出现什么？","options":["两块各有南北磁极","单独一个纯北极","完全没有磁性","只剩电池"],"correct_option_index":0,"explanation":"普通磁体分开后每块仍会有两个磁极。"},{"question":"把冰块放入装满水的杯子后，冰融化会让水面必定大幅升高吗？","options":["必定升高十倍","水变成固体","水全部蒸发","不会，漂浮冰融化通常不改变水面高度"],"correct_option_index":3,"explanation":"漂浮冰排开的水重与融化后的水相等。"},{"question":"如果将盐加入纯水，盐完全溶解后会发生什么？","options":["水变成金属","盐一定沉到底部","形成均匀盐水混合物","盐原子消失"],"correct_option_index":2,"explanation":"盐溶解后以离子形式分散在水中。"},{"question":"热气球能够上升，最直接的原因是？","options":["云朵牵引","球内热空气整体密度比外面空气低","空气变得没有重力","地面磁铁推着球"],"correct_option_index":1,"explanation":"温差造成的密度差产生净浮力。"},{"question":"普通玻璃杯里的铅笔浸在水中看起来折弯了，主要原因？","options":["光的折射","铅笔真的折断","杯子发出电磁波","空气停止流动"],"correct_option_index":0,"explanation":"光在空气与水交界面改变传播方向。"},{"question":"当月亮呈现满月，是否意味着它自己发出可见光？","options":["是，像灯泡发电","是，火山持续发光","月亮完全透明","不是，主要反射太阳光"],"correct_option_index":3,"explanation":"满月亮光主要是太阳光反射。"},{"question":"红色衣服在白光下呈红色，主要由于它？","options":["吸收全部红光","把蓝光变成水","反射较多红色波段的光","创造红色光子"],"correct_option_index":2,"explanation":"物体颜色与吸收和反射的光谱有关。"},{"question":"你把金属勺与木勺放在同一室温一晚后摸起来金属更凉，为什么？","options":["金属没有温度","金属传热更快","金属必定温度更低","木勺会自己发热"],"correct_option_index":1,"explanation":"触感受热传导速率影响很大。"},{"question":"想看清细胞内的细节，哪种工具通常比肉眼更合适？","options":["显微镜","指南针","听诊器","温度计"],"correct_option_index":0,"explanation":"显微镜能放大微小结构。"},{"question":"同样的声音在空气和真空中传播，正确的说法是？","options":["真空中传播更快","真空中回声更响","空气让声音消失","真空中不能靠普通声波传播"],"correct_option_index":3,"explanation":"声波需要介质，真空不支持普通声音传播。"},{"question":"一台风扇朝你吹风，为什么常会觉得更凉？","options":["空气没有质量","风扇让体温自动归零","空气流动加速皮肤散热及汗液蒸发","风扇直接制造冷量"],"correct_option_index":2,"explanation":"气流增强对流和蒸发散热。"},{"question":"把一张纸揉成团再放开，纸团的总质量在没有碎屑丢失时怎样？","options":["必定变成两倍","基本不变","突然变成零","必定增加十倍"],"correct_option_index":1,"explanation":"改变形状并不会创造或消灭纸的物质。"},{"question":"如果让手电筒光照射墙壁，再用手挡在中间，为什么墙上出现影子？","options":["部分光被手遮挡","手把光染成黑色","墙壁吸收所有空气","手掌产生黑光"],"correct_option_index":0,"explanation":"不透明物体阻挡光传播会形成阴影。"}]},{"id":"c8202611-05c0-4a9b-9f00-000000000003","title":"怪兽数学餐厅：荒诞但算得清","subject":"搞怪数学","grade_level":"Year 6","language":"zh","description":"20 道幽默情境的准确数学题：怪兽、飞碟、披萨与魔法商店。","questions":[{"question":"三头怪兽每头戴4顶帽子，总共有几顶帽子？","options":["9顶","16顶","12顶","7顶"],"correct_option_index":2,"explanation":"按题意列式计算，3×4=12。"},{"question":"外星人买6杯月球奶茶，每杯RM5，需要付多少钱？","options":["RM36","RM30","RM11","RM25"],"correct_option_index":1,"explanation":"按题意列式计算，6×5=30。"},{"question":"一条龙有18颗糖，平均分给3只小恐龙，每只几颗？","options":["6颗","9颗","3颗","15颗"],"correct_option_index":0,"explanation":"按题意列式计算，18÷3=6。"},{"question":"飞碟每秒移动7米，5秒移动多少米？","options":["12米","42米","28米","35米"],"correct_option_index":3,"explanation":"按题意列式计算，7×5=35。"},{"question":"魔法商店有48支羽毛笔，卖出19支，还剩多少支？","options":["27支","39支","29支","31支"],"correct_option_index":2,"explanation":"按题意列式计算，48−19=29。"},{"question":"机器人用2分钟叠8件衣服，同样速度10分钟叠几件？","options":["20件","40件","16件","80件"],"correct_option_index":1,"explanation":"每分钟4件，10分钟40件。"},{"question":"吸血鬼买一块RM80的披风，打七五折（付原价75%），应付多少？","options":["RM60","RM20","RM75","RM65"],"correct_option_index":0,"explanation":"80×0.75=60。"},{"question":"史莱姆一开始重4千克，分裂成两个相同质量的小史莱姆，每个重多少？","options":["4千克","8千克","1千克","2千克"],"correct_option_index":3,"explanation":"假设没有质量流失，平均分为两份。"},{"question":"幽灵电影院有7排座椅，每排12个座位，总座位数？","options":["72个","96个","84个","19个"],"correct_option_index":2,"explanation":"按题意列式计算，7×12=84。"},{"question":"小怪兽有100枚金币，买了3件每件17枚金币的衣服，还剩多少？","options":["39枚","49枚","51枚","47枚"],"correct_option_index":1,"explanation":"总花费51枚，100−51=49。"},{"question":"魔法火锅里有36颗丸子，6个锅平均分，每锅几颗？","options":["6颗","8颗","5颗","12颗"],"correct_option_index":0,"explanation":"按题意列式计算，36÷6=6。"},{"question":"一架UFO绕操场飞4圈，每圈400米，总路程？","options":["1000米","800米","2000米","1600米"],"correct_option_index":3,"explanation":"4×400=1600。"},{"question":"忍者猫每3分钟吃1块饼干，连续吃15分钟共吃几块？","options":["6块","15块","5块","3块"],"correct_option_index":2,"explanation":"在每满3分钟吃1块的设定下，15÷3=5。"},{"question":"神秘盒每个装9颗星星贴纸，11个盒子共有多少颗？","options":["89颗","99颗","90颗","101颗"],"correct_option_index":1,"explanation":"按题意列式计算，9×11=99。"},{"question":"魔法师的长袍价格RM120，优惠20%，节省多少钱？","options":["RM24","RM20","RM96","RM30"],"correct_option_index":0,"explanation":"120×20%=24。"},{"question":"章鱼画家有8只腕，每只拿1支画笔，共拿几支？","options":["16支","4支","12支","8支"],"correct_option_index":3,"explanation":"每只腕1支，一共8支。"},{"question":"幽灵电梯从2楼上升5层，抵达哪一楼？","options":["6楼","10楼","7楼","5楼"],"correct_option_index":2,"explanation":"按题意列式计算，2+5=7。"},{"question":"两只机器人各造15个积木，合并后拿走8个，剩多少？","options":["38个","22个","30个","15个"],"correct_option_index":1,"explanation":"2×15−8=22。"},{"question":"独角兽绕圆形草地走一圈，若直径是10米，取圆周率3.14，约走多远？","options":["31.4米","20米","15.7米","314米"],"correct_option_index":0,"explanation":"周长=圆周率×直径=31.4米。"},{"question":"外星汉堡店每份卖RM12，进货成本RM7，卖出10份的毛利是多少（不计其他成本）？","options":["RM70","RM120","RM190","RM50"],"correct_option_index":3,"explanation":"每份毛利RM5，10份共RM50。"}]},{"id":"c8202611-05c0-4a9b-9f00-000000000004","title":"外星人密码本：怪逻辑训练","subject":"外星逻辑","grade_level":"Year 7","language":"zh","description":"20 道有明确定义规则的外星密码题，训练规律、条件和演绎。","questions":[{"question":"火星规则：每个数字都加3。地球数字5变成什么？","options":["53","8","2","15"],"correct_option_index":1,"explanation":"按题意列式计算，按规则5+3=8。"},{"question":"水星规则：每个数乘2再减1。输入4，输出多少？","options":["7","8","6","9"],"correct_option_index":0,"explanation":"按题意列式计算，4×2−1=7。"},{"question":"月球密码把字母A变B、B变C，C会变成哪个字母？","options":["B","E","A","D"],"correct_option_index":3,"explanation":"每个字母向后移动一个位置。"},{"question":"机器人说“噜”代表红色，“啦”代表蓝色。它说“啦”，颜色是什么？","options":["绿色","黄色","蓝色","红色"],"correct_option_index":2,"explanation":"题目已明确定义“啦”的意思。"},{"question":"外星门的密码必须是偶数，以下哪个符合？","options":["49","24","17","35"],"correct_option_index":1,"explanation":"按题意列式计算，24可被2整除。"},{"question":"飞船楼层编号依次为2、4、8、16，下一个按每次乘2是多少？","options":["32","20","24","18"],"correct_option_index":0,"explanation":"每个数是前一个的两倍。"},{"question":"如果火星语“ZOR”代表3，“MIP”代表5，那么“ZOR+MIP”代表的数值和是？","options":["15","2","35","8"],"correct_option_index":3,"explanation":"按题意列式计算，3+5=8。"},{"question":"密码由前三位数字1、2、3按顺序组成，下一位每次加1，应是？","options":["6","0","4","1"],"correct_option_index":2,"explanation":"按连续整数规律，3之后是4。"},{"question":"外星电梯只停3的倍数楼层，下面哪个可以停？","options":["25楼","21楼","20楼","22楼"],"correct_option_index":1,"explanation":"21÷3=7，为整数。"},{"question":"规则“圆圈=2分，三角形=3分”，两个圆圈和一个三角形共几分？","options":["7分","5分","8分","9分"],"correct_option_index":0,"explanation":"按题意列式计算，2×2+3=7。"},{"question":"某机器把输入数字减2再平方。输入5，结果是？","options":["23","25","7","9"],"correct_option_index":3,"explanation":"按题意列式计算，(5−2)²=9。"},{"question":"外星日历一周只有5天，从第一天再过7天（以第一天为0），是第几天？","options":["第4天","第5天","第3天","第2天"],"correct_option_index":2,"explanation":"7除以5余2，所以第一天向后移两天是第三天。"},{"question":"机器人只会在两个按钮都亮时开门。按钮A亮、B不亮，会怎样？","options":["永远损坏","不开门","开门","随机爆炸"],"correct_option_index":1,"explanation":"AND条件要求A与B同时为真。"},{"question":"机器人在任一按钮亮时开门。A不亮、B亮，会怎样？","options":["开门","不开门","只亮灯","无法判断"],"correct_option_index":0,"explanation":"OR条件只需至少一个为真。"},{"question":"飞船名字按字母顺序A、C、E、G排列，下一个应是？","options":["H","J","K","I"],"correct_option_index":3,"explanation":"每次向后跳过一个英文字母。"},{"question":"密码检查器规定长度恰好为4的字符串才通过。哪个能通过？","options":["SPACE","STARSHIP","MOON","SUN"],"correct_option_index":2,"explanation":"MOON有4个字母。"},{"question":"三个星球按大小排序：A比B大，B比C大。最大的是？","options":["三者一样","A","B","C"],"correct_option_index":1,"explanation":"由传递关系A>B>C。"},{"question":"机器人将“猫”编码为7、“狗”编码为9。这两个编码相加是多少？","options":["16","79","2","63"],"correct_option_index":0,"explanation":"7+9=16，题目只要求数值相加。"},{"question":"一颗星星标记代表4点，两个星星标记再加1点是多少？","options":["8点","10点","5点","9点"],"correct_option_index":3,"explanation":"按题意列式计算，4+4+1=9。"},{"question":"两台机器只在信号相同时显示OK。信号分别为0和1，结果是？","options":["显示两个OK","随机选择","不显示OK","显示OK"],"correct_option_index":2,"explanation":"两个信号不同，不符合相同条件。"}]},{"id":"c8202611-05c0-4a9b-9f00-000000000005","title":"Animals That Sound Made Up","subject":"Weird Animals","grade_level":"Year 7","language":"en","description":"20 genuinely strange animal facts, explained without myths or exaggeration.","questions":[{"question":"How many hearts does a typical octopus have?","options":["Three","One","Seven","Zero"],"correct_option_index":0,"explanation":"Octopuses have two hearts serving the gills and one pumping blood through the body."},{"question":"Why can an octopus''s blood look blue?","options":["It drinks blue seawater","It contains blue ink","Its blood has no oxygen carrier","It uses copper-containing hemocyanin"],"correct_option_index":3,"explanation":"Hemocyanin uses copper in oxygen transport, giving the blood a blue appearance."},{"question":"Which animal is a mammal that lays eggs?","options":["Tiger","Bat","Platypus","Dolphin"],"correct_option_index":2,"explanation":"Platypuses are monotremes, a small group of egg-laying mammals."},{"question":"In seahorses, which parent typically carries developing young in a brood pouch?","options":["Neither parent","Male","Female","Both in the same shared pouch"],"correct_option_index":1,"explanation":"Male seahorses carry embryos in a specialised brood pouch."},{"question":"Why are many flamingos pink?","options":["Pigments obtained through their diet","Their bones glow pink","They produce pink light","They paint their feathers"],"correct_option_index":0,"explanation":"Carotenoid pigments from food influence their feather colour."},{"question":"What are a pangolin''s protective scales mostly made of?","options":["Glass","Calcium carbonate crystals only","Metal","Keratin"],"correct_option_index":3,"explanation":"Pangolin scales consist of keratin, a protein also found in hair and nails."},{"question":"Which body part do butterflies use to sense some tastes?","options":["Antennae only","Eyes only","Feet","Wings only"],"correct_option_index":2,"explanation":"Taste receptors on butterfly feet help detect suitable plants."},{"question":"What is unusual about a starfish or sea star''s usual movement?","options":["It jumps using springs","It uses many tiny tube feet","It flies using feathers","It has rolling wheels"],"correct_option_index":1,"explanation":"Sea stars use a water vascular system and tube feet for movement."},{"question":"What feature helps a gecko grip many smooth surfaces?","options":["Tiny specialised structures on its toe pads","Permanent glue on its claws","Magnetic shoes","Electric suction motors"],"correct_option_index":0,"explanation":"Microscopic structures on gecko toes enable strong contact with surfaces."},{"question":"What is a narwhal''s famous long tusk actually?","options":["A horn made of bone alone","A branch stuck to its head","A second tail","An elongated tooth"],"correct_option_index":3,"explanation":"A narwhal tusk develops from a specialised tooth."},{"question":"Which bird is famous for running fast but cannot fly?","options":["Hummingbird","Albatross","Ostrich","Penguin"],"correct_option_index":2,"explanation":"Ostriches are large flightless birds capable of rapid running."},{"question":"What helps many chameleons see in different directions at once?","options":["Transparent bones","Eyes that move largely independently","A second head","Mirrors attached to ears"],"correct_option_index":1,"explanation":"Many chameleons can move their eyes independently to survey surroundings."},{"question":"What is an axolotl widely known for?","options":["Regenerating some lost body parts","Breathing fire","Turning into a bird","Producing electricity like a battery"],"correct_option_index":0,"explanation":"Axolotls can regenerate limbs and other tissues."},{"question":"What is a tardigrade?","options":["A newly discovered moon","A type of tropical tree","A giant carnivorous bird","A tiny eight-legged invertebrate"],"correct_option_index":3,"explanation":"Tardigrades are microscopic animals also called water bears."},{"question":"Why are coral reefs built partly by animals?","options":["Fish weld metal","Crabs manufacture plastic","Coral polyps secrete calcium carbonate skeletons","Whales arrange stones"],"correct_option_index":2,"explanation":"Many reef-building corals make hard skeletons over time."},{"question":"Which mammal is capable of sustained true flight?","options":["Koala","Bat","Flying squirrel","Sugar glider"],"correct_option_index":1,"explanation":"Bats can fly using powered wing strokes; gliding mammals cannot sustain powered flight."},{"question":"How do many cuttlefish rapidly alter their visible colours?","options":["They control pigment-containing skin cells","They swap entire skins every second","They spray coloured seawater onto themselves","Their bones contain LED lights"],"correct_option_index":0,"explanation":"Chromatophores and other skin structures help change appearance."},{"question":"Which creature is a close relative of the octopus?","options":["Jellyfish","Sea turtle","Sea urchin","Squid"],"correct_option_index":3,"explanation":"Octopuses and squids are cephalopod molluscs."},{"question":"What do many bees communicate with a waggle dance?","options":["Their age in human years","Which flower has the loudest sound","Information about a food source''s direction and distance","Tomorrow''s exact weather"],"correct_option_index":2,"explanation":"Honeybee dances can convey spatial information about food."},{"question":"Why is a sloth''s fur sometimes greenish?","options":["Its skin emits green light","Algae may grow on its fur","It is made entirely of leaves","Sloths are actually plants"],"correct_option_index":1,"explanation":"Algae living in sloth fur can contribute to a greenish tint."}]},{"id":"c8202611-05c0-4a9b-9f00-000000000006","title":"Space Has No Chill: Strange Solar System","subject":"Strange Space","grade_level":"Year 7","language":"en","description":"20 surprising but grounded space facts, including bizarre rotation and impossible vacations.","questions":[{"question":"Which planet''s rotation period is longer than its year around the Sun?","options":["Earth","Mars","Jupiter","Venus"],"correct_option_index":3,"explanation":"Venus takes about 243 Earth days to rotate once and about 225 days to orbit."},{"question":"On which planet would the Sun appear to rise in the west due to retrograde rotation?","options":["Earth","Mercury","Venus","Mars"],"correct_option_index":2,"explanation":"Venus rotates opposite the direction typical of most planets."},{"question":"Which planet appears to roll on its side because of its extreme axial tilt?","options":["Mercury","Uranus","Venus","Earth"],"correct_option_index":1,"explanation":"Uranus has an axial tilt near 90 degrees."},{"question":"In a scale-model museum, which Solar System planet needs the largest sphere?","options":["Jupiter","Earth","Venus","Mars"],"correct_option_index":0,"explanation":"Jupiter has the largest diameter and mass among the planets."},{"question":"Why can astronauts float inside a spacecraft orbiting Earth?","options":["Earth''s gravity completely disappears","They have no mass","Spacecraft generate magical anti-gravity","They and the spacecraft are in continuous free fall"],"correct_option_index":3,"explanation":"An orbit is a form of continuous free fall."},{"question":"Could you safely stand on the Sun''s visible surface like solid ground?","options":["Yes, because it is made of rock","Yes, only at night","No, it is hot plasma without a solid surface","Yes, with ordinary shoes"],"correct_option_index":2,"explanation":"The Sun is a star composed mainly of extremely hot gas and plasma."},{"question":"Which object is Earth''s natural satellite?","options":["The Sun","The Moon","Mars","Venus"],"correct_option_index":1,"explanation":"The Moon is Earth''s natural satellite."},{"question":"What is an asteroid?","options":["A small rocky or metallic Solar System body","A new type of cloud","A black hole inside Earth","A man-made satellite only"],"correct_option_index":0,"explanation":"Asteroids are smaller bodies orbiting the Sun, often rocky."},{"question":"How does sunlight reach Earth through the vacuum of space?","options":["By sound waves carried through vacuum","By ocean currents","Through a rope from the Sun","As electromagnetic radiation"],"correct_option_index":3,"explanation":"Light travels through vacuum as electromagnetic waves."},{"question":"Why do stars appear to twinkle when viewed from Earth?","options":["They shake Earth''s ground","Their colour disappears every second","Our atmosphere bends their light unevenly","They repeatedly turn off and on"],"correct_option_index":2,"explanation":"Atmospheric turbulence changes the path of starlight."},{"question":"Why might a person weigh less on the Moon than on Earth?","options":["Space suits contain weight-removing magnets","The Moon''s gravitational pull at its surface is weaker","The person''s mass disappears","The Moon has no gravity"],"correct_option_index":1,"explanation":"Weight depends on local gravity, but mass remains nearly the same."},{"question":"What causes the phases of the Moon?","options":["We see differing portions of its sunlit half","Earth changes the Moon''s shape","The Moon turns its lamp on and off","Moon rocks change colour weekly"],"correct_option_index":0,"explanation":"Lunar phase depends on Sun-Moon-Earth geometry."},{"question":"Why does a comet often develop a tail near the Sun?","options":["It is a rocket with a permanent exhaust","It catches fire like wood","It leaves ink in space","Solar heating releases gas and dust pushed away by sunlight and solar wind"],"correct_option_index":3,"explanation":"Heat-driven outgassing creates a coma and tails."},{"question":"Which planet is known for a prominent system of icy rings?","options":["Earth","Mars","Saturn","Mercury"],"correct_option_index":2,"explanation":"Saturn''s rings contain abundant ice particles."},{"question":"Where is the main asteroid belt located?","options":["Beyond the observable universe","Between Mars and Jupiter","Between Earth and the Moon","Inside the Sun"],"correct_option_index":1,"explanation":"The main belt occupies orbits between Mars and Jupiter."},{"question":"What is a light-year?","options":["A distance travelled by light in one year","A type of calendar month","A single day on Venus","The age of all stars"],"correct_option_index":0,"explanation":"A light-year is a unit of distance, not time."},{"question":"Why is Mars often called the Red Planet?","options":["Its seas are filled with red paint","It reflects only radio waves","Every rock there is hot lava","Iron-rich dust and minerals give it a reddish appearance"],"correct_option_index":3,"explanation":"Iron oxide contributes to Mars''s colour."},{"question":"How many Sun-like stars are at the centre of our Solar System?","options":["Eight","None","One","Two"],"correct_option_index":2,"explanation":"Our planetary system orbits one star, the Sun."},{"question":"Why is space not completely empty even far from Earth?","options":["All galaxies have identical density","Sparse particles and radiation can still exist","Every region contains breathable air","Space is filled with liquid water everywhere"],"correct_option_index":1,"explanation":"Interplanetary and interstellar space contain thin matter and radiation."},{"question":"What would an ordinary unprotected human hear from a distant explosion in the vacuum of space?","options":["No sound transmitted through vacuum","A louder bang than on Earth","A low rumble travelling faster than light","Only an echo from the Moon"],"correct_option_index":0,"explanation":"Sound needs a material medium to carry pressure waves."}]},{"id":"c8202611-05c0-4a9b-9f00-000000000007","title":"Impossible Physics: What If...? ","subject":"Physics What-Ifs","grade_level":"Year 7","language":"en","description":"20 absurd imaginary experiments with real scientific reasoning and clearly stated assumptions.","questions":[{"question":"If you drop a hammer and a feather together in a perfect vacuum, which hits first from the same height?","options":["The feather","Neither object falls","They land together","The hammer"],"correct_option_index":2,"explanation":"In a vacuum both have the same free-fall acceleration."},{"question":"If Earth suddenly had no atmosphere, could ordinary speech travel through open air?","options":["Only speech in English","No","Yes, at exactly the same speed","Only whispered speech"],"correct_option_index":1,"explanation":"Sound pressure waves require a medium."},{"question":"If you place a working magnet near a plastic spoon, what should happen in normal conditions?","options":["The spoon is not strongly attracted like iron","It always flies to the magnet","It turns into steel","It starts glowing"],"correct_option_index":0,"explanation":"Most ordinary plastics are not ferromagnetic."},{"question":"A sealed transparent jar contains a plant. Can the plant receive light through the glass?","options":["No, all glass blocks visible light","Only if the jar is blue","Only at midnight","Yes, if the glass transmits that light"],"correct_option_index":3,"explanation":"Ordinary transparent glass lets much visible light through."},{"question":"You place an object in a mirror''s reflection. Does the reflected object have real physical mass behind the mirror?","options":["Twice the object''s mass","It depends on the time","No","Yes, equal to the object''s mass"],"correct_option_index":2,"explanation":"A mirror image is a virtual image, not a physical duplicate."},{"question":"If a submarine dives deeper, what generally happens to the surrounding water pressure?","options":["It changes to air pressure only","It increases","It goes to zero","It always decreases"],"correct_option_index":1,"explanation":"Hydrostatic pressure generally rises with depth."},{"question":"Why does a helium-filled balloon tend to rise in ordinary air?","options":["Its total average density is lower than displaced air","Helium has no mass","Air has no gravity","The balloon is secretly a rocket"],"correct_option_index":0,"explanation":"Buoyancy exceeds the total weight of a light balloon."},{"question":"Could an ordinary flashlight beam be heard as a spoken sentence in vacuum by itself?","options":["Yes, because light is sound","Yes, if the beam is red","Only if you travel faster than it","No"],"correct_option_index":3,"explanation":"Electromagnetic radiation and sound waves are different phenomena."},{"question":"If you put an ice cube in a glass of pure water, what usually happens first?","options":["The ice disappears instantly","The ice turns into salt","The ice floats","The ice sinks like steel"],"correct_option_index":2,"explanation":"Ice is usually less dense than liquid water."},{"question":"If you break a bar magnet in half, how many separate magnetic poles does each ordinary fragment have?","options":["No poles in every case","A north and a south pole","Only a north pole","Only a south pole"],"correct_option_index":1,"explanation":"Breaking a conventional magnet produces smaller dipoles."},{"question":"If you push a wheeled cart on a smoother floor with the same force, friction is usually...?","options":["Lower","Always higher","Exactly infinite","Unrelated to contact surfaces"],"correct_option_index":0,"explanation":"Less friction typically opposes motion on smoother matched surfaces."},{"question":"What happens to a shadow when an opaque object blocks a beam of light?","options":["The object converts light into liquid","Light turns into gravity","All surfaces turn black permanently","A darker region appears behind it"],"correct_option_index":3,"explanation":"An object prevents some light from reaching the surface."},{"question":"If you put a hot metal spoon into cooler water, which way does heat naturally flow at first?","options":["No heat can transfer","From the spoon directly into sunlight","From the spoon toward the water","From the cooler water into the hotter spoon only"],"correct_option_index":2,"explanation":"Heat transfer occurs from higher to lower temperature."},{"question":"If a rubber band stretches, where is energy stored while it is held stretched?","options":["Only chemical fuel","Elastic potential energy","Only nuclear energy","Nothing stores energy"],"correct_option_index":1,"explanation":"Deformation stores recoverable elastic energy."},{"question":"Why can a prism split white light into colours?","options":["Different wavelengths refract by different amounts","Light has tiny paint droplets","The prism generates new colours from nothing","White light contains no wavelengths"],"correct_option_index":0,"explanation":"Dispersion separates light wavelengths due to different refractive indices."},{"question":"An astronaut takes off their boots while orbiting. Does their body stop having mass?","options":["Yes","Only if shoes are white","Only during sleep","No"],"correct_option_index":3,"explanation":"Mass is intrinsic; weightlessness does not remove mass."},{"question":"In a vacuum chamber, an electric bell visibly vibrates. What does a person outside hear through the chamber walls if well isolated acoustically?","options":["The bell speaks a language","A sound that travels without matter","Little or no sound from the vibrating bell through vacuum","A louder bell than in air"],"correct_option_index":2,"explanation":"Ordinary sound cannot cross vacuum; structure-borne leakage depends on isolation."},{"question":"Would a solar panel generate its usual electrical output in complete darkness with no other illumination?","options":["Only on cloudy days","No","Yes, at full power","Yes, because it stores infinite sunlight"],"correct_option_index":1,"explanation":"Photovoltaic panels need incident light to generate power."},{"question":"If you double the time a constant-speed robot moves while keeping its speed unchanged, its travel distance...?","options":["Doubles","Halves","Becomes zero","Stays identical"],"correct_option_index":0,"explanation":"Distance equals speed times time."},{"question":"If you use a perfect balance to compare 2 kg of sand and 2 kg of marshmallows, which has greater mass?","options":["The marshmallows","The sand","The lighter-looking one","Neither; masses are equal"],"correct_option_index":3,"explanation":"Both samples have a mass of 2 kg."}]},{"id":"c8202611-05c0-4a9b-9f00-000000000008","title":"Ridiculous Inventions, Sensible Engineering","subject":"Wacky Inventions","grade_level":"Year 7","language":"en","description":"20 comically odd inventions that teach practical engineering trade-offs and safety.","questions":[{"question":"You invent a hat that catches rainwater. What should you consider first?","options":["How to promise it cures disease","Whether collected water is clean and safe","How to make it weigh 50 kg","How to hide its weight from wearers"],"correct_option_index":1,"explanation":"Collected rainwater can be contaminated and needs proper treatment before drinking."},{"question":"A robot spoon keeps spilling soup. Which design improvement is most useful?","options":["Add a steadier gripping and motion control system","Make the spoon invisible","Remove all sensors","Increase motion speed without testing"],"correct_option_index":0,"explanation":"Controlled movements can reduce spills."},{"question":"Your shoes have tiny fans. Which factor limits how long they can run?","options":["The colour of the laces","The wearer''s favourite number","The day of the week","Available battery energy"],"correct_option_index":3,"explanation":"Powered fans need an energy source."},{"question":"A backpack automatically lights up at night. Which sensor could help?","options":["A compass that measures weight","A ruler","Ambient light sensor","Only a thermometer"],"correct_option_index":2,"explanation":"A light sensor detects low illumination."},{"question":"A smart umbrella keeps opening in strong wind. What design challenge matters?","options":["How many stickers fit on a handle","Wind loads on its frame and hinges","The number of emojis on it","Whether it has a catchy name"],"correct_option_index":1,"explanation":"Wind produces forces that can damage an umbrella."},{"question":"You invent a quiet alarm for a deaf user. Which alternative output could help?","options":["A strong vibration or flashing visual signal","Only a very soft sound","A hidden audio recording","A message in invisible ink"],"correct_option_index":0,"explanation":"Multimodal alerts improve accessibility."},{"question":"A solar-powered toy works only in sunlight. What is a practical way to use it after dark?","options":["Paint the toy yellow","Remove its solar panel","Cover its battery compartment","Add a rechargeable energy store"],"correct_option_index":3,"explanation":"Stored electrical energy can power the toy when illumination is absent."},{"question":"An automatic pencil sharpener jams when a pencil is crooked. What could improve reliability?","options":["Remove all safety stops","Force users to push harder","Guide the pencil into the correct position","Use weaker materials without testing"],"correct_option_index":2,"explanation":"Alignment and protective stops can prevent jams."},{"question":"You invent a floating chair for a swimming pool. What must be tested?","options":["How many hashtags it gets","Buoyancy, stability and user safety","Only its colour","Whether it has music"],"correct_option_index":1,"explanation":"Water devices need stability and safety checks."},{"question":"A robot planter waters crops every hour even when soil is wet. What should you add?","options":["Soil moisture sensing and threshold logic","A louder speaker","Random watering times only","More decorative wheels"],"correct_option_index":0,"explanation":"Sensors can reduce unnecessary irrigation."},{"question":"An absurd giant straw is 20 metres long. What may make drinking through it difficult?","options":["The colour of the straw","Whether it has stripes","The person''s hairstyle","Pressure differences and fluid resistance"],"correct_option_index":3,"explanation":"A long tube increases resistance and may exceed practical suction limits."},{"question":"A bicycle helmet is designed like a pineapple. What matters more than its appearance?","options":["Adding the tallest decorative leaf","Increasing weight as much as possible","Impact protection and proper fit","Matching the bicycle colour exactly"],"correct_option_index":2,"explanation":"Helmet safety depends on certified protection and fit."},{"question":"A phone-controlled toaster accidentally heats while unattended. What safety feature is important?","options":["Making the heating element exposed","Automatic shutoff and temperature limits","More notification sounds only","Removing the power indicator"],"correct_option_index":1,"explanation":"Fail-safe shutdown reduces fire risk."},{"question":"Your robotic pencil case keeps opening in a bag. Which sensor or mechanism helps?","options":["A secure latch with intentional opening control","An always-on motor","Loose hinges","A bigger logo"],"correct_option_index":0,"explanation":"A latch prevents accidental opening."},{"question":"An elevator can play music but its emergency button is hidden. What is the highest-priority fix?","options":["Add more songs","Change the background wallpaper","Increase speaker volume","Make emergency controls accessible and visible"],"correct_option_index":3,"explanation":"Safety controls outrank entertainment features."},{"question":"An AI-powered fridge guesses every meal incorrectly. How should the team improve it?","options":["Delete all error reports","Ask users for passwords","Test real needs and correct unreliable assumptions","Claim 100% accuracy anyway"],"correct_option_index":2,"explanation":"Feedback and measurable testing support improvement."},{"question":"A paper bridge collapses under a stack of books. What should you do?","options":["Increase the stack without analysis","Test stronger folds and load paths","Keep using the same shape without change","Hide the collapse"],"correct_option_index":1,"explanation":"Fold geometry can improve strength and load distribution."},{"question":"An umbrella follows its owner using GPS but collides with people. Which capability is missing?","options":["Reliable local obstacle detection and avoidance","A longer product name","More decorative colours","A louder motor only"],"correct_option_index":0,"explanation":"GPS alone does not detect nearby moving obstacles."},{"question":"A classroom scoreboard updates slowly on bad Wi-Fi. What design helps?","options":["Infinite retries without limits","Hiding all error messages","Requiring users to click 100 times","Graceful offline/error states and recovery"],"correct_option_index":3,"explanation":"Explicit recovery and bounded retry improve reliability."},{"question":"A robot cat has ten blinking lights but no privacy policy. What should a responsible designer prioritise?","options":["Collect all nearby contacts silently","Store plaintext passwords","Explain data collection and protect user information","Make lights blink faster"],"correct_option_index":2,"explanation":"Privacy and security are essential even for playful devices."}]},{"id":"c8202611-05c0-4a9b-9f00-000000000009","title":"Detective Duck: Tiny Mysteries with Clues","subject":"Funny Mysteries","grade_level":"Year 7","language":"en","description":"20 playful mini-detective mysteries where all clues are given and there is only one correct deduction.","questions":[{"question":"Three pets are a cat, a dog and a rabbit. The rabbit is in the blue room, the dog is in the green room. Who is in the red room?","options":["The cat","The dog","The rabbit","No pet"],"correct_option_index":0,"explanation":"With each pet assigned a different room, the remaining cat is in red."},{"question":"Mira, Leo and Nia own red, green and blue umbrellas. Mira has red, Leo does not have blue. Which colour does Nia have?","options":["Green","Red","Yellow","Blue"],"correct_option_index":3,"explanation":"Leo must have green; Nia gets blue."},{"question":"A thief left muddy footprints, but the floor had been dry and locked all day before a rainstorm. Which event most likely happened after rain began?","options":["The rain fell indoors without an opening","The prints are magnetic","Someone walked inside with wet shoes","The floor cleaned itself"],"correct_option_index":2,"explanation":"Wet muddy prints suggest someone entered after becoming muddy outside."},{"question":"Only one of three boxes contains a coin. Box A is empty and box C is empty. Where is the coin?","options":["No box","Box B","Box A","Box C"],"correct_option_index":1,"explanation":"Only B remains as the possible location."},{"question":"A note says \"the secret is the first letter of CAT\". Which letter is the secret?","options":["C","A","T","D"],"correct_option_index":0,"explanation":"The first letter of CAT is C."},{"question":"A detective''s watch stopped at 14:10. It has not moved since. What does its display show at 18:00?","options":["18:00","14:18","00:00","14:10"],"correct_option_index":3,"explanation":"A stopped watch does not change its display."},{"question":"A robot leaves a room at 09:15 and returns 20 minutes later. When does it return?","options":["09:45","10:15","09:35","09:25"],"correct_option_index":2,"explanation":"15 minutes past 9 plus 20 minutes is 35 minutes past 9."},{"question":"The suspect''s gloves are dry, but a wet glove is found outside. Can you identify the suspect from this fact alone?","options":["Yes; the tallest person","No; more evidence is needed","Yes; definitely the person with a blue shirt","Yes; any person nearby"],"correct_option_index":1,"explanation":"A single glove observation cannot identify its owner conclusively."},{"question":"Three suspects have badges 11, 12 and 13. The clue says the badge number is even. Which badge matches?","options":["12","11","13","All three"],"correct_option_index":0,"explanation":"Only 12 is divisible by two."},{"question":"A museum has four doors. Only the north door was opened in the event log. Which door should investigators examine first for recorded entry?","options":["South door","West door","East door","North door"],"correct_option_index":3,"explanation":"The entry log points to the north door; other evidence may still matter."},{"question":"A parrot repeats exactly the last word it hears. You say \"yellow banana\". What does it repeat?","options":["yellow banana","parrot","banana","yellow"],"correct_option_index":2,"explanation":"By the given rule it repeats only the final word."},{"question":"The code is the number of letters in MOON plus the number in STAR. What is the code?","options":["16","8","7","9"],"correct_option_index":1,"explanation":"MOON has four letters and STAR has four, giving eight."},{"question":"All five biscuits are in a locked tin. Someone takes out two and does not replace them. How many remain in the tin?","options":["3","2","5","7"],"correct_option_index":0,"explanation":"Five minus two leaves three."},{"question":"A detective needs to visit rooms A, B and C once each. She has visited A and B. Which room remains?","options":["A","B","D","C"],"correct_option_index":3,"explanation":"Only room C is unvisited."},{"question":"A password clue says \"a 3-digit code starting 42 and ending 7\". What code fits?","options":["247","4270","427","472"],"correct_option_index":2,"explanation":"The first two digits are 42 and the last is 7."},{"question":"A message was sent at 11:00 and received at 11:02. Assuming clocks are synchronised, how long did delivery take?","options":["20 minutes","2 minutes","1 minute","12 minutes"],"correct_option_index":1,"explanation":"11:02 minus 11:00 is two minutes."},{"question":"If only red cards trigger the alarm, and a blue card was scanned, should the alarm trigger under this rule?","options":["No","Yes","Only on weekends","Only with two blue cards"],"correct_option_index":0,"explanation":"The stated rule triggers on red cards only."},{"question":"A detective compares two identical-sized bottles: one is full and one is half-full. Which contains more liquid?","options":["The half-full bottle","They contain equal liquid","Neither contains liquid","The full bottle"],"correct_option_index":3,"explanation":"Equal capacity with one full means the full one holds more."},{"question":"The laboratory door opens only if both lights are green. One light is green, the other red. What happens?","options":["It disappears","It turns into a window","It stays locked","It opens"],"correct_option_index":2,"explanation":"Both-green condition is not met."},{"question":"A security camera recorded three visitors entering and two exiting, with no other entrances or exits. How many of those visitors remain inside?","options":["5","1","2","3"],"correct_option_index":1,"explanation":"Three entered and two left, leaving one of the recorded visitors."}]},{"id":"c8202611-05c0-4a9b-9f00-000000000010","title":"Everyday Things That Are Surprisingly Weird","subject":"Weird Everyday Science","grade_level":"Year 6","language":"en","description":"20 quirky household phenomena with solid explanations: static hair, soap bubbles, popcorn and more.","questions":[{"question":"Why does popcorn suddenly pop when heated?","options":["The kernel is magnetic","Salt makes it explode by itself","The corn turns into metal","Water inside the kernel becomes pressurised steam"],"correct_option_index":3,"explanation":"Steam pressure builds until the kernel ruptures."},{"question":"Why can a rubbed balloon stick to a wall?","options":["The wall becomes a magnet","Air stops having gravity","Static electric attraction","The balloon creates permanent glue"],"correct_option_index":2,"explanation":"Transferred electric charge can produce attraction."},{"question":"Why do soap bubbles often look rainbow-coloured?","options":["Soap is naturally made of tiny rainbows","Thin-film interference separates reflected light colours","Bubbles contain rainbow paint","Water creates LEDs"],"correct_option_index":1,"explanation":"Light reflecting from a thin film interferes at different wavelengths."},{"question":"Why can wet fingers make a glass surface seem slippery?","options":["A water film changes friction at the contact surface","Water eliminates all forces","Glass becomes soft like butter","The fingers stop having skin"],"correct_option_index":0,"explanation":"Lubrication alters friction between surfaces."},{"question":"Why do onions sometimes make eyes water when cut?","options":["They produce salty tears directly","Onions are radioactive","Their colour blocks vision","They release irritating volatile chemicals"],"correct_option_index":3,"explanation":"Cutting onions releases compounds that irritate the eyes."},{"question":"Why can a metal spoon feel colder than a wooden one in the same room?","options":["Wood creates sunlight","Metal is always below freezing","Metal transfers heat away from skin more quickly","Metal has no temperature"],"correct_option_index":2,"explanation":"Thermal conductivity affects how rapidly skin loses heat."},{"question":"Why does a straw make liquid rise when you sip?","options":["The glass pushes liquid using electricity","Lower pressure inside the straw lets surrounding pressure push liquid up","The straw attracts water magnetically","Your mouth creates gravity"],"correct_option_index":1,"explanation":"Pressure differences drive the liquid upward."},{"question":"Why does a fan often make sweaty skin feel cooler?","options":["It increases evaporation and heat transfer","It turns air into ice","It switches off body heat","It changes Earth''s orbit"],"correct_option_index":0,"explanation":"Moving air speeds evaporation and convection."},{"question":"Why can you see your breath on a chilly morning?","options":["Your lungs make smoke","Oxygen turns into visible metal","Air becomes solid everywhere","Moist breath forms tiny liquid droplets in cool air"],"correct_option_index":3,"explanation":"Cooling water vapour can form a visible mist."},{"question":"Why does an unopened cold soda sometimes fizz when opened?","options":["Sugar turns into fire","The bottle becomes magnetic","Dissolved carbon dioxide escapes as pressure falls","Oxygen always burns the drink"],"correct_option_index":2,"explanation":"Lower pressure allows dissolved gas to form bubbles."},{"question":"Why can ice make a drink float with cubes on top?","options":["Ice is made of air only","Ice is less dense than liquid water","Ice has no mass","The glass pushes it upward magnetically"],"correct_option_index":1,"explanation":"A lower-density solid floats in a denser liquid."},{"question":"Why does cut apple flesh often brown after exposure to air?","options":["Enzymatic reactions involving oxygen","The apple absorbs sunlight as paint","Its sugar turns into iron","The peel changes to metal"],"correct_option_index":0,"explanation":"Polyphenol oxidase contributes to browning reactions."},{"question":"Why do shadows grow longer when a low Sun shines near the horizon?","options":["Objects become taller at sunset","Gravity gets stronger each evening","The ground tilts suddenly","The light arrives at a shallow angle"],"correct_option_index":3,"explanation":"Low-angle sunlight stretches the shadow."},{"question":"Why can a lid on a jar be easier to open after warming it slightly?","options":["The jar turns into rubber","The lid loses all friction","Heating may expand the lid enough to loosen it","Warm water removes gravity"],"correct_option_index":2,"explanation":"Different thermal expansion can help loosen the fit."},{"question":"Why does water form rounded drops on some waxy leaves?","options":["The leaf becomes magnetic","Surface tension and poor wetting of the leaf surface","Leaves generate marbles","Water stops being a liquid"],"correct_option_index":1,"explanation":"Cohesive forces and surface chemistry shape droplets."},{"question":"Why can sugar seem to disappear when stirred into water?","options":["It dissolves and disperses among water molecules","It leaves the universe","It transforms into air automatically","The spoon absorbs all sugar"],"correct_option_index":0,"explanation":"Dissolved sugar remains in the solution."},{"question":"What makes a rubber ball bounce?","options":["It contains a gravity switch","Air always pushes it upward forever","It has a hidden motor in every case","Elastic deformation stores and returns some energy"],"correct_option_index":3,"explanation":"Material elasticity returns some stored energy after impact."},{"question":"Why do mirrors show a reversed-looking image without producing a second person?","options":["They make time flow backward","They project your body behind the wall","They redirect incoming light into a virtual image","They duplicate human bodies"],"correct_option_index":2,"explanation":"Mirror reflections create virtual images from redirected light."},{"question":"Why is a rainbow often seen with the Sun behind the observer?","options":["Rainwater contains coloured dust by default","Water droplets bend, reflect and disperse sunlight toward the viewer","Clouds grow coloured wires","The Sun becomes a laser screen"],"correct_option_index":1,"explanation":"The viewing geometry of sunlight and droplets creates a rainbow."},{"question":"Why does bread dough with yeast often rise?","options":["Yeast produces carbon dioxide that forms bubbles in dough","Flour becomes magnetic","Water transforms into stone","Air pressure vanishes"],"correct_option_index":0,"explanation":"Fermentation can release gas trapped by the dough''s structure."}]},{"id":"c8202611-05c0-4a9b-9f00-000000000011","title":"Teka-Teki Pelik Tapi Logik","subject":"Teka-Teki Pelik","grade_level":"Tahun 6","language":"ms","description":"20 teka-teki lucu dengan satu jawapan yang jelas dan penerangan Bahasa Melayu.","questions":[{"question":"Dalam setahun ada 12 bulan. Berapa bulan mempunyai sekurang-kurangnya 28 hari?","options":["2","6","12","1"],"correct_option_index":2,"explanation":"Semua bulan mempunyai sekurang-kurangnya 28 hari."},{"question":"Ada 5 biji epal di meja. Kamu ambil 3. Berapa biji epal yang ada di tangan kamu?","options":["8","3","2","5"],"correct_option_index":1,"explanation":"Soalan bertanya epal yang diambil, bukan yang masih di atas meja."},{"question":"Yang manakah lebih berat, 1 kg kapas atau 1 kg besi?","options":["Sama berat","Kapas","Besi","Tidak boleh dibandingkan"],"correct_option_index":0,"explanation":"Kedua-duanya berjisim satu kilogram."},{"question":"Seekor robot mempunyai 4 roda. Tiga robot sama mempunyai berapa roda?","options":["7","8","16","12"],"correct_option_index":3,"explanation":"3 darab 4 bersamaan 12 roda."},{"question":"Kamu memotong sebiji piza kepada 4 bahagian sama besar. Berapa bahagian semuanya?","options":["8","1","4","2"],"correct_option_index":2,"explanation":"Bilangan kepingan yang dinyatakan ialah empat."},{"question":"Terdapat 10 ekor ikan di dalam akuarium. Dua mati tetapi tidak dikeluarkan. Berapa ekor masih di dalam akuarium?","options":["12","10","8","2"],"correct_option_index":1,"explanation":"Ikan mati tetap berada dalam akuarium jika tidak dikeluarkan."},{"question":"Jam digital menunjukkan 10:00. Selepas 45 minit, apakah waktunya?","options":["10:45","10:30","11:45","09:45"],"correct_option_index":0,"explanation":"45 minit selepas pukul sepuluh ialah 10:45."},{"question":"Tiga raksasa masing-masing mempunyai dua mata. Jumlah semua mata mereka?","options":["3","9","12","6"],"correct_option_index":3,"explanation":"3 raksasa darab 2 mata bersamaan 6."},{"question":"Jika hari ini hari Isnin, tiga hari kemudian hari apa?","options":["Jumaat","Ahad","Khamis","Rabu"],"correct_option_index":2,"explanation":"Selasa hari pertama, Rabu kedua, Khamis ketiga."},{"question":"Ada 6 pensel. Dua diberi kepada kawan dan satu hilang. Berapa pensel tinggal?","options":["5","3","4","2"],"correct_option_index":1,"explanation":"6 tolak 2 tolak 1 bersamaan 3."},{"question":"Sebuah UFO membawa 7 makhluk asing. Dua turun dan tiga naik. Berapa penumpang sekarang?","options":["8","6","10","12"],"correct_option_index":0,"explanation":"Kiraannya ialah 7−2+3=8."},{"question":"Ada 4 pasang kasut. Berapa kasut individu semuanya?","options":["4","6","12","8"],"correct_option_index":3,"explanation":"Setiap pasang mempunyai dua kasut."},{"question":"Sebuah buku mempunyai 20 halaman. Kamu baca 5 halaman. Berapa halaman belum dibaca?","options":["10","5","15","25"],"correct_option_index":2,"explanation":"20 tolak 5 sama dengan 15."},{"question":"Dua ekor kucing masing-masing makan 3 biskut. Berapa biskut dimakan?","options":["9","6","5","3"],"correct_option_index":1,"explanation":"2 darab 3 bersamaan 6."},{"question":"Kereta elektrik tanpa enjin pembakaran bergerak. Adakah ia mengeluarkan asap ekzos pembakaran seperti kereta petrol?","options":["Tidak","Ya, sentiasa","Hanya pada waktu malam","Hanya ketika hujan"],"correct_option_index":0,"explanation":"Kereta elektrik tanpa sumber pembakaran tidak menghasilkan asap ekzos enjin petrol."},{"question":"Kamu berada di tempat kedua dalam perlumbaan dan memintas peserta pertama. Kamu kini nombor berapa?","options":["Kedua","Ketiga","Terakhir","Pertama"],"correct_option_index":3,"explanation":"Memintas orang pertama menjadikan kamu peserta pertama."},{"question":"Sebiji tembikai dibahagi kepada 8 potongan sama besar. Empat potongan dimakan. Berapa potongan tinggal?","options":["2","6","4","8"],"correct_option_index":2,"explanation":"Kiraannya ialah 8−4=4."},{"question":"Lampu berkelip sekali setiap 2 saat. Dalam 10 saat, jika ia berkelip pada saat 2,4,6,8,10, berapa kali?","options":["10","5","4","6"],"correct_option_index":1,"explanation":"Lima waktu yang disenaraikan menghasilkan lima kelipan."},{"question":"Ada 9 kerusi. Tujuh kerusi diduduki satu orang setiap satu. Berapa kerusi kosong?","options":["2","3","7","9"],"correct_option_index":0,"explanation":"9−7=2 kerusi kosong."},{"question":"Mesin menghasilkan 5 pelekat setiap minit. Berapa pelekat dalam 4 minit?","options":["9","15","25","20"],"correct_option_index":3,"explanation":"5 pelekat seminit darab 4 minit bersamaan 20."}]},{"id":"c8202611-05c0-4a9b-9f00-000000000012","title":"Sains Pelik: Betul atau Mengarut?","subject":"Sains Pelik","grade_level":"Tahun 7","language":"ms","description":"20 soalan sains yang pelik tetapi berdasarkan fenomena sebenar dan logik eksperimen.","questions":[{"question":"Mengapakah sudu logam terasa lebih sejuk daripada sudu kayu pada suhu bilik yang sama?","options":["Logam menghasilkan ais","Logam memindahkan haba daripada tangan lebih cepat","Logam tidak mempunyai suhu","Kayu selalu lebih panas"],"correct_option_index":1,"explanation":"Kekonduksian haba logam lebih tinggi."},{"question":"Mengapa ais biasanya terapung di dalam air?","options":["Ais kurang tumpat daripada air cecair","Ais tidak mempunyai jisim","Ais diperbuat daripada udara","Air ialah magnet"],"correct_option_index":0,"explanation":"Ketumpatan ais lebih rendah berbanding air cecair."},{"question":"Dalam ruang vakum, bolehkah bunyi loceng bergerak terus melalui ruang kosong?","options":["Ya, lebih kuat","Ya, tanpa had","Hanya jika loceng merah","Tidak"],"correct_option_index":3,"explanation":"Gelombang bunyi biasa memerlukan medium untuk merambat."},{"question":"Mengapa pensel dalam gelas air kelihatan bengkok?","options":["Air menukar pensel menjadi getah","Gelas menghasilkan bayang hitam","Pembiasan cahaya","Pensel patah apabila disentuh air"],"correct_option_index":2,"explanation":"Cahaya berubah arah apabila merentasi air dan udara."},{"question":"Apakah yang menyebabkan pelangi terbentuk?","options":["Petir melukis warna","Cahaya matahari dibiaskan, dipantulkan dan diuraikan oleh titisan air","Awan menghasilkan cat","Udara menjadi logam"],"correct_option_index":1,"explanation":"Cahaya berinteraksi dengan titisan air untuk menghasilkan spektrum."},{"question":"Mengapakah belon yang digosok boleh melekat pada dinding?","options":["Tarikan elektrostatik","Belon menghasilkan gam kekal","Dinding menjadi besi","Udara kehilangan graviti"],"correct_option_index":0,"explanation":"Cas elektrik boleh menghasilkan daya tarikan."},{"question":"Mengapa bayang-bayang menjadi panjang apabila matahari rendah?","options":["Objek menjadi semakin tinggi","Graviti bertambah setiap petang","Tanah memanjang","Sudut cahaya matahari lebih rendah"],"correct_option_index":3,"explanation":"Sudut cahaya mempengaruhi panjang bayang."},{"question":"Tumbuhan hijau memerlukan gas manakah untuk fotosintesis?","options":["Nitrogen sahaja","Hidrogen tulen","Karbon dioksida","Helium"],"correct_option_index":2,"explanation":"Tumbuhan mengambil karbon dioksida untuk menghasilkan gula."},{"question":"Apakah fungsi utama akar tumbuhan?","options":["Mencipta cahaya matahari","Menyerap air dan mineral serta membantu menyokong tumbuhan","Menghasilkan bunyi muzik","Membina awan"],"correct_option_index":1,"explanation":"Akar menyerap bahan dari tanah dan memberi sokongan."},{"question":"Mengapakah kita dapat melihat Bulan bersinar?","options":["Bulan memantulkan cahaya matahari","Bulan mempunyai lampu elektrik","Bulan diperbuat daripada api","Bulan menghasilkan semua cahaya sendiri"],"correct_option_index":0,"explanation":"Cahaya Bulan yang kelihatan kebanyakannya ialah pantulan cahaya matahari."},{"question":"Planet manakah mengambil masa putaran paksi lebih lama daripada tempoh orbitnya mengelilingi Matahari?","options":["Bumi","Marikh","Musytari","Zuhrah"],"correct_option_index":3,"explanation":"Zuhrah berputar dalam kira-kira 243 hari Bumi dan mengorbit dalam kira-kira 225 hari."},{"question":"Planet manakah kelihatan berputar mengiring kerana kecondongan paksinya yang sangat besar?","options":["Bumi","Marikh","Uranus","Utarid"],"correct_option_index":2,"explanation":"Paksi Uranus condong hampir 90 darjah."},{"question":"Sotong kurita biasanya mempunyai berapa jantung?","options":["Lapan","Tiga","Satu","Lima"],"correct_option_index":1,"explanation":"Dua jantung mengepam darah ke insang dan satu ke seluruh badan."},{"question":"Mengapa darah sotong kurita boleh kelihatan biru?","options":["Protein hemocyanin mengandungi kuprum","Ia meminum air berwarna biru","Ia tidak mempunyai darah","Insangnya mengeluarkan cat"],"correct_option_index":0,"explanation":"Hemocyanin menggunakan kuprum untuk membawa oksigen."},{"question":"Mengapakah air mendidih pada suhu lebih rendah di gunung tinggi?","options":["Air menjadi unsur lain","Gunung menarik haba keluar sepenuhnya","Air kehilangan molekul","Tekanan udara lebih rendah"],"correct_option_index":3,"explanation":"Tekanan rendah menurunkan suhu didih air."},{"question":"Mengapa udara bergerak daripada kipas sering menyejukkan kulit berpeluh?","options":["Ia menghentikan haba badan","Kipas mengubah orbit Bumi","Ia mempercepat penyejatan dan pemindahan haba","Ia membuat ketulan ais dalam udara"],"correct_option_index":2,"explanation":"Pengaliran udara meningkatkan penyejatan peluh."},{"question":"Apakah yang menyebabkan jagung bertih meletup ketika dipanaskan?","options":["Biji jagung menerima arus elektrik","Tekanan wap air meningkat di dalam biji jagung","Jagung menjadi magnet","Gula bertukar menjadi logam"],"correct_option_index":1,"explanation":"Wap air yang terperangkap meningkatkan tekanan sehingga kulit pecah."},{"question":"Mengapa air gula boleh menjadi jernih selepas dikacau?","options":["Gula larut dan tersebar di dalam air","Gula hilang dari alam semesta","Gula menjadi batu","Sudu menyerap semua gula"],"correct_option_index":0,"explanation":"Molekul gula masih berada dalam larutan."},{"question":"Mengapakah kita dapat melihat wap seperti kabus daripada nafas pada pagi sejuk?","options":["Paru-paru menghasilkan asap kebakaran","Oksigen menjadi besi","Udara menjadi pejal","Wap air dalam nafas terkondensasi menjadi titisan kecil"],"correct_option_index":3,"explanation":"Udara sejuk membolehkan titisan kecil terbentuk."},{"question":"Apakah yang berlaku kepada jisim 2 kg kapas apabila dibandingkan dengan 2 kg batu menggunakan neraca tepat?","options":["Batu lebih berat","Jisimnya menjadi sifar","Kedua-duanya mempunyai jisim yang sama","Kapas lebih berat"],"correct_option_index":2,"explanation":"Kedua-duanya ialah dua kilogram walaupun isipadunya berbeza."}]}]'::jsonb AS packs), expanded AS (
 SELECT p.value AS pack,q.value AS item,(q.ordinality-1)::integer AS position
 FROM payload CROSS JOIN LATERAL jsonb_array_elements(payload.packs) AS p(value)
 CROSS JOIN LATERAL jsonb_array_elements(p.value->'questions') WITH ORDINALITY AS q(value,ordinality)
)
INSERT INTO public.questions(quiz_set_id,position,question,choices,correct_index,explanation)
SELECT (e.pack->>'id')::uuid,e.position,e.item->>'question',e.item->'options',
 (e.item->>'correct_option_index')::smallint,e.item->>'explanation'
FROM expanded e JOIN public.quiz_sets s
 ON s.id=(e.pack->>'id')::uuid AND s.title=e.pack->>'title'
 AND s.owner_user_id IS NULL AND s.status='published'
WHERE NOT EXISTS (SELECT 1 FROM public.questions previous WHERE previous.quiz_set_id=s.id AND previous.position=e.position);
DO $zokivo$
DECLARE pack_count integer; question_count integer; uneven integer; bad_question integer; overlap integer;
BEGIN
 SELECT count(*) INTO pack_count FROM public.quiz_sets WHERE id IN ('c8202611-05c0-4a9b-9f00-000000000001'::uuid,'c8202611-05c0-4a9b-9f00-000000000002'::uuid,'c8202611-05c0-4a9b-9f00-000000000003'::uuid,'c8202611-05c0-4a9b-9f00-000000000004'::uuid,'c8202611-05c0-4a9b-9f00-000000000005'::uuid,'c8202611-05c0-4a9b-9f00-000000000006'::uuid,'c8202611-05c0-4a9b-9f00-000000000007'::uuid,'c8202611-05c0-4a9b-9f00-000000000008'::uuid,'c8202611-05c0-4a9b-9f00-000000000009'::uuid,'c8202611-05c0-4a9b-9f00-000000000010'::uuid,'c8202611-05c0-4a9b-9f00-000000000011'::uuid,'c8202611-05c0-4a9b-9f00-000000000012'::uuid) AND status='published' AND owner_user_id IS NULL;
 SELECT count(*) INTO question_count FROM public.questions WHERE quiz_set_id IN ('c8202611-05c0-4a9b-9f00-000000000001'::uuid,'c8202611-05c0-4a9b-9f00-000000000002'::uuid,'c8202611-05c0-4a9b-9f00-000000000003'::uuid,'c8202611-05c0-4a9b-9f00-000000000004'::uuid,'c8202611-05c0-4a9b-9f00-000000000005'::uuid,'c8202611-05c0-4a9b-9f00-000000000006'::uuid,'c8202611-05c0-4a9b-9f00-000000000007'::uuid,'c8202611-05c0-4a9b-9f00-000000000008'::uuid,'c8202611-05c0-4a9b-9f00-000000000009'::uuid,'c8202611-05c0-4a9b-9f00-000000000010'::uuid,'c8202611-05c0-4a9b-9f00-000000000011'::uuid,'c8202611-05c0-4a9b-9f00-000000000012'::uuid);
 SELECT count(*) INTO uneven FROM (
   SELECT quiz_set_id,count(*) n FROM public.questions WHERE quiz_set_id IN ('c8202611-05c0-4a9b-9f00-000000000001'::uuid,'c8202611-05c0-4a9b-9f00-000000000002'::uuid,'c8202611-05c0-4a9b-9f00-000000000003'::uuid,'c8202611-05c0-4a9b-9f00-000000000004'::uuid,'c8202611-05c0-4a9b-9f00-000000000005'::uuid,'c8202611-05c0-4a9b-9f00-000000000006'::uuid,'c8202611-05c0-4a9b-9f00-000000000007'::uuid,'c8202611-05c0-4a9b-9f00-000000000008'::uuid,'c8202611-05c0-4a9b-9f00-000000000009'::uuid,'c8202611-05c0-4a9b-9f00-000000000010'::uuid,'c8202611-05c0-4a9b-9f00-000000000011'::uuid,'c8202611-05c0-4a9b-9f00-000000000012'::uuid)
   GROUP BY quiz_set_id HAVING count(*)<>20
 ) x;
 SELECT count(*) INTO bad_question FROM public.questions WHERE quiz_set_id IN ('c8202611-05c0-4a9b-9f00-000000000001'::uuid,'c8202611-05c0-4a9b-9f00-000000000002'::uuid,'c8202611-05c0-4a9b-9f00-000000000003'::uuid,'c8202611-05c0-4a9b-9f00-000000000004'::uuid,'c8202611-05c0-4a9b-9f00-000000000005'::uuid,'c8202611-05c0-4a9b-9f00-000000000006'::uuid,'c8202611-05c0-4a9b-9f00-000000000007'::uuid,'c8202611-05c0-4a9b-9f00-000000000008'::uuid,'c8202611-05c0-4a9b-9f00-000000000009'::uuid,'c8202611-05c0-4a9b-9f00-000000000010'::uuid,'c8202611-05c0-4a9b-9f00-000000000011'::uuid,'c8202611-05c0-4a9b-9f00-000000000012'::uuid)
 AND (correct_index NOT BETWEEN 0 AND 3 OR jsonb_typeof(choices)<>'array'
      OR jsonb_array_length(choices)<>4 OR length(trim(question))<4 OR length(trim(explanation))<10);
 WITH stems AS (
 SELECT lower(trim(q.question)) stem,
  count(*) FILTER(WHERE q.quiz_set_id IN ('c8202611-05c0-4a9b-9f00-000000000001'::uuid,'c8202611-05c0-4a9b-9f00-000000000002'::uuid,'c8202611-05c0-4a9b-9f00-000000000003'::uuid,'c8202611-05c0-4a9b-9f00-000000000004'::uuid,'c8202611-05c0-4a9b-9f00-000000000005'::uuid,'c8202611-05c0-4a9b-9f00-000000000006'::uuid,'c8202611-05c0-4a9b-9f00-000000000007'::uuid,'c8202611-05c0-4a9b-9f00-000000000008'::uuid,'c8202611-05c0-4a9b-9f00-000000000009'::uuid,'c8202611-05c0-4a9b-9f00-000000000010'::uuid,'c8202611-05c0-4a9b-9f00-000000000011'::uuid,'c8202611-05c0-4a9b-9f00-000000000012'::uuid)) new_count,count(*) all_count
 FROM public.questions q JOIN public.quiz_sets s ON s.id=q.quiz_set_id
 WHERE s.status='published' GROUP BY lower(trim(q.question))
 ) SELECT count(*) INTO overlap FROM stems WHERE new_count>0 AND all_count>new_count;
 IF pack_count<>12 OR question_count<>240 OR uneven<>0 OR bad_question<>0 OR overlap<>0 THEN
 RAISE EXCEPTION 'Weird Wonder content integrity failed: packs %, questions %, uneven %, malformed %, duplicates %',
 pack_count,question_count,uneven,bad_question,overlap;
 END IF;
END $zokivo$;
COMMIT;
